values ((select id from guides where slug = $pb$freidoras-de-aire-menos-100$pb$), 1, $pb$Cosori 5,7 L$pb$, $pb$Mejor en general$pb$, $pb$La opción más equilibrada para una casa de tres o cuatro personas. Tiene 5,7 litros de capacidad, 1700 W y un rango de 75 a 205 ºC, con programas preestablecidos y control táctil. Su punto diferencial está dentro: la cámara de cocción está libre de PFAS y el interior es metálico. Incluye además un recetario de 40 recetas. Lo que pega: el cable de un metro obliga a tenerla cerca del enchufe.$pb$, array[$pb$Cámara de cocción libre de PFAS e interior metálico$pb$, $pb$Capacidad de 5,7 L, buena para tres o cuatro personas$pb$, $pb$Rango de temperatura amplio, hasta 205 ºC$pb$]::text[], array[$pb$Cable de solo un metro$pb$, $pb$No baja de 75 ºC, así que no sirve para deshidratar$pb$]::text[], $pb$[{"label":"Capacidad","value":"5,7 L"},{"label":"Potencia","value":"1700 W"},{"label":"Temperatura","value":"75-205 ºC"},{"label":"Control","value":"Táctil"},{"label":"Peso","value":"5,4 kg"}]$pb$::jsonb);
