values ((select id from guides where slug = $pb$freidoras-de-aire-menos-100$pb$), 2, $pb$Philips 2000 Airfryer 6,2 L$pb$, $pb$La más cómoda de usar$pb$, $pb$Pensada para quien quiere meter la comida, elegir un modo y olvidarse. Tiene 6,2 litros, 13 modos de cocinado en pantalla táctil y una ventana integrada para ver cómo va sin abrir la cesta. Las piezas van al lavavajillas y la app HomeID da recetas y pasos guiados adaptados a esta freidora. Es una buena elección para familias pequeñas que cocinan a diario. Lo que pega: el cuerpo es de plástico y ocupa más de 40 cm de fondo.$pb$, array[$pb$Ventana para vigilar la cocción sin abrir$pb$, $pb$Piezas aptas para lavavajillas$pb$, $pb$13 modos y app de recetas HomeID$pb$]::text[], array[$pb$Carcasa de plástico$pb$, $pb$Ocupa bastante fondo en la encimera$pb$]::text[], $pb$[{"label":"Capacidad","value":"6,2 L"},{"label":"Potencia","value":"1700 W"},{"label":"Temperatura","value":"60-200 ºC"},{"label":"Modos","value":"13"},{"label":"Extras","value":"Ventana y app HomeID"}]$pb$::jsonb);
