values ((select id from guides where slug = $pb$freidoras-de-aire-menos-100$pb$), 3, $pb$Philips 1000 doble cesta 7,1 L$pb$, $pb$Para familias$pb$, $pb$Si en casa sois cuatro o más, la doble cesta cambia la forma de cocinar: haces el pollo en un lado y las patatas en el otro, y la cocción sincronizada consigue que terminen a la vez. Suma 7,1 litros en total, 2450 W y 10 funciones entre freír, asar y hornear, con acceso a la app HomeID. Es la más potente de la guía. Lo que pega: casi 44 cm de ancho, se maneja con botones en lugar de pantalla táctil y cada cesta por separado es más pequeña que una cesta única.$pb$, array[$pb$Dos cestas con cocción sincronizada$pb$, $pb$2450 W, la más potente de la lista$pb$, $pb$Rango de temperatura desde 40 ºC$pb$]::text[], array[$pb$Muy ancha, necesita hueco en la encimera$pb$, $pb$Control por botones, sin pantalla táctil$pb$]::text[], $pb$[{"label":"Capacidad","value":"7,1 L (dos cestas)"},{"label":"Potencia","value":"2450 W"},{"label":"Temperatura","value":"40-200 ºC"},{"label":"Funciones","value":"10"},{"label":"Ancho","value":"43,8 cm"}]$pb$::jsonb);
