values ((select id from guides where slug = $pb$freidoras-de-aire-menos-100$pb$), 5, $pb$Cecotec Fantastik Window 4000$pb$, $pb$Si quieres gastar lo mínimo$pb$, $pb$La más barata y la más compacta de la lista, ideal para una o dos personas o para una cocina pequeña. Tiene 4 litros, 1400 W, 9 modos preconfigurados y una ventana que se ilumina durante la cocción para ver la comida sin abrir. El temporizador llega a 60 minutos y cuenta con protección contra sobrecalentamiento. Es una buena primera freidora para probar si te encaja. Lo que pega: se queda corta para familias y la temperatura mínima de 80 ºC limita algunos usos.$pb$, array[$pb$La más barata y compacta de la guía$pb$, $pb$Ventana iluminada para vigilar la cocción$pb$, $pb$Protección contra sobrecalentamiento$pb$]::text[], array[$pb$4 L, se queda corta para más de dos personas$pb$, $pb$Temperatura mínima de 80 ºC$pb$]::text[], $pb$[{"label":"Capacidad","value":"4 L"},{"label":"Potencia","value":"1400 W"},{"label":"Temperatura","value":"80-200 ºC"},{"label":"Modos","value":"9"},{"label":"Temporizador","value":"0-60 min"}]$pb$::jsonb);
