values ((select id from guides where slug = $pb$auriculares-inalambricos-menos-50$pb$), 1, $pb$Soundcore P31i$pb$, $pb$Mejor en general$pb$, $pb$Auriculares de botón muy completos para su rango. Tienen cancelación de ruido adaptativa, que ajusta el nivel según el entorno, sonido de alta resolución con LDAC y seis micrófonos para llamadas en la calle. Aguantan 12 horas por carga (8 con la cancelación activada) y hasta 50 horas con el estuche. Como extra, traducen conversaciones en tiempo real en más de cien idiomas. Lo que pega: el LDAC solo funciona con móviles Android compatibles y el control es táctil, que no a todo el mundo le gusta.$pb$, array[$pb$Cancelación de ruido adaptativa$pb$, $pb$Hasta 50 horas con el estuche$pb$, $pb$Seis micrófonos para llamadas$pb$]::text[], array[$pb$LDAC solo con Android compatible$pb$, $pb$Controles táctiles, fáciles de tocar sin querer$pb$]::text[], $pb$[{"label":"Tipo","value":"Intraurales (botón)"},{"label":"Cancelación de ruido","value":"Adaptativa"},{"label":"Autonomía","value":"12 h (50 h con estuche)"},{"label":"Autonomía con ANC","value":"8 h (40 h con estuche)"},{"label":"Micrófonos","value":"6"},{"label":"Códec","value":"LDAC"}]$pb$::jsonb);
