values ((select id from guides where slug = $pb$auriculares-inalambricos-menos-50$pb$), 2, $pb$Soundcore Q20i$pb$, $pb$Para viajar$pb$, $pb$Cascos de diadema con cancelación de ruido híbrida, con dos micrófonos internos y dos externos, pensados para aviones, trenes y oficinas ruidosas. Montan drivers de 40 mm y aguantan 40 horas con la cancelación encendida o 60 sin ella, así que en un viaje largo no te acordarás del cargador. Se conectan a dos dispositivos a la vez, tienen modo transparencia y la app ofrece 22 ecualizaciones. Lo que pega: son supraaurales, con lo que pueden apretar en sesiones largas, y usan Bluetooth 5.0, una versión algo antigua.$pb$, array[$pb$Cancelación de ruido híbrida$pb$, $pb$Hasta 60 horas sin ANC$pb$, $pb$Conexión a dos dispositivos y modo transparencia$pb$]::text[], array[$pb$Supraaurales: pueden cansar la oreja$pb$, $pb$Bluetooth 5.0$pb$]::text[], $pb$[{"label":"Tipo","value":"Diadema supraaural"},{"label":"Cancelación de ruido","value":"Híbrida"},{"label":"Autonomía","value":"60 h (40 h con ANC)"},{"label":"Drivers","value":"40 mm"},{"label":"Bluetooth","value":"5.0, multipunto"}]$pb$::jsonb);
