values ((select id from guides where slug = $pb$auriculares-inalambricos-menos-50$pb$), 3, $pb$Sony WH-CH520$pb$, $pb$Para llamadas y teletrabajo$pb$, $pb$Unos cascos ligeros, de 147 gramos, para quien pasa muchas horas con ellos puestos y salta del portátil al móvil. Tienen conexión multipunto, micrófono integrado, botones físicos y emparejamiento rápido con Swift Pair y Fast Pair. La batería llega a 50 horas y con tres minutos de carga tienes hora y media de música. La app permite ajustar un ecualizador de cinco bandas. Lo que pega: no tienen cancelación de ruido, así que en sitios ruidosos se quedan atrás frente a los Soundcore.$pb$, array[$pb$Muy ligeros, 147 g$pb$, $pb$Multipunto y botones físicos$pb$, $pb$50 horas de batería con carga rápida$pb$]::text[], array[$pb$Sin cancelación de ruido$pb$, $pb$Aíslan poco en transporte público$pb$]::text[], $pb$[{"label":"Tipo","value":"Diadema"},{"label":"Peso","value":"147 g"},{"label":"Autonomía","value":"50 h"},{"label":"Carga rápida","value":"3 min = 90 min"},{"label":"Control","value":"Botones"},{"label":"Ecualizador","value":"5 bandas en app"}]$pb$::jsonb);
