values ((select id from guides where slug = $pb$auriculares-inalambricos-menos-50$pb$), 4, $pb$JBL Tune 520BT$pb$, $pb$Para llevar en la mochila$pb$, $pb$Cascos plegables y ligeros para quien quiere sonido con graves marcados y olvidarse del cargador. Aguantan hasta 57 horas, se cargan por USB-C en unas dos horas y con cinco minutos de carga sacas tres horas de música. Usan Bluetooth 5.3 y la app de JBL incluye ecualizador y Voice Aware, para oír tu propia voz durante las llamadas. Lo que pega: no tienen cancelación de ruido y, al ser supraaurales, en sesiones largas pueden apretar un poco.$pb$, array[$pb$Hasta 57 horas de batería$pb$, $pb$Diseño plegable$pb$, $pb$Bluetooth 5.3 y carga USB-C$pb$]::text[], array[$pb$Sin cancelación de ruido$pb$, $pb$Supraaurales: aislamiento limitado$pb$]::text[], $pb$[{"label":"Tipo","value":"Diadema supraaural plegable"},{"label":"Autonomía","value":"57 h"},{"label":"Carga rápida","value":"5 min = 3 h"},{"label":"Bluetooth","value":"5.3"},{"label":"Conector de carga","value":"USB-C"}]$pb$::jsonb);
