values ((select id from guides where slug = $pb$auriculares-inalambricos-menos-50$pb$), 5, $pb$Soundcore P20i$pb$, $pb$Si quieres gastar lo mínimo$pb$, $pb$Los más baratos de la guía y una buena puerta de entrada a los auriculares de botón. Tienen resistencia IPX5 al agua y al sudor, así que sirven para el gimnasio o para salir a correr con lluvia. Dan 10 horas por carga y 30 con el estuche, que trae un cordón para colgarlo. La app ofrece 22 ecualizaciones y una función para buscar un auricular perdido. Lo que pega: no tienen cancelación de ruido y tienen la autonomía total más corta de la guía (30 h con el estuche).$pb$, array[$pb$Resistentes al agua y al sudor (IPX5)$pb$, $pb$Función para localizar un auricular perdido$pb$, $pb$Estuche pequeño con cordón$pb$]::text[], array[$pb$Sin cancelación de ruido$pb$, $pb$La autonomía total más corta de la guía (30 h con el estuche)$pb$]::text[], $pb$[{"label":"Tipo","value":"Intraurales (botón)"},{"label":"Autonomía","value":"10 h (30 h con estuche)"},{"label":"Resistencia","value":"IPX5"},{"label":"Drivers","value":"10 mm"},{"label":"Bluetooth","value":"5.3"}]$pb$::jsonb);
