values ((select id from guides where slug = $pb$robots-aspiradores-menos-300$pb$), 1, $pb$Roborock Qrevo 2 Pro$pb$, $pb$Mejor en general$pb$, $pb$El más completo de la guía y el que menos trabajo te deja. Su base vacía el polvo, rellena el depósito de agua, lava la mopa a 75 ºC y la seca con aire templado. Aspira con hasta 25 000 Pa, sube la potencia en alfombras y retira la mopa cuando pasa por ellas. Su brazo FlexiArm friega muy cerca de las paredes y esquiva zapatos y juguetes. Lo que pega: roza el tope de la guía y la base ocupa bastante más que la de un robot sencillo.$pb$, array[$pb$Base que vacía, rellena agua, lava y seca la mopa$pb$, $pb$Retira la mopa al pasar por alfombras$pb$, $pb$Sistema antienredos doble para pelo largo$pb$]::text[], array[$pb$El más caro de la lista, al límite del tope$pb$, $pb$Base voluminosa$pb$]::text[], $pb$[{"label":"Succión","value":"25 000 Pa"},{"label":"Navegación","value":"SLAM con evitación de obstáculos"},{"label":"Lavado de mopa","value":"Automático a 75 ºC"},{"label":"Filtro","value":"HEPA"},{"label":"Suelos","value":"Duros y alfombras"}]$pb$::jsonb);
