values ((select i.id from guide_items i where i.guide_id = (select id from guides where slug = $pb$robots-aspiradores-menos-300$pb$) and i.position = 1), 'amazon', $pb$B0GZZ96X7N$pb$, $pb$https://www.amazon.es/dp/B0GZZ96X7N$pb$, 0);
insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$robots-aspiradores-menos-300$pb$), 2, $pb$Dreame D20 Air Plus$pb$, $pb$Mejor relación calidad-precio$pb$, $pb$Tiene base de autovaciado con bolsa de 4 litros, que según el fabricante da para unos 120 días sin tocarla, y 20 000 Pa de succión. Aspira y friega a la vez con caudal de agua regulable, sube la potencia sola al detectar alfombras y lleva cepillos antienredos. La batería anuncia hasta 300 minutos. Es una buena elección para casas medianas y grandes con mascotas. Lo que pega: la base no lava la mopa, así que esa parte sigue siendo tuya.$pb$, array[$pb$Autovaciado con bolsa de 4 L$pb$, $pb$Succión de 20 000 Pa$pb$, $pb$Batería de hasta 300 minutos$pb$]::text[], array[$pb$La mopa se lava a mano$pb$, $pb$Las bolsas de la base son un gasto recurrente$pb$]::text[], $pb$[{"label":"Succión","value":"20 000 Pa"},{"label":"Autovaciado","value":"Bolsa de 4 L"},{"label":"Autonomía","value":"300 min"},{"label":"Ancho de limpieza","value":"39 cm"},{"label":"Filtro","value":"HEPA"}]$pb$::jsonb);
