values ((select id from guides where slug = $pb$robots-aspiradores-menos-300$pb$), 3, $pb$Dreame D10 Plus Gen 2$pb$, $pb$Para alfombras y pelo de mascota$pb$, $pb$Un robot con autovaciado que cuida especialmente las alfombras gracias a su cepillo de goma flotante, que se adapta a la superficie y se enreda poco con el pelo. Aspira con 6000 Pa en cuatro niveles, vacía el depósito en una bolsa de 4 litros y anuncia hasta 285 minutos de batería. Crea mapas editables, admite zonas prohibidas y se controla por app o por voz. Lo que pega: el depósito de agua es pequeño, de 150 ml, así que el fregado es para repasos ligeros.$pb$, array[$pb$Autovaciado con bolsa de 4 L$pb$, $pb$Cepillo de goma flotante, bueno con el pelo$pb$, $pb$Control por voz y zonas prohibidas$pb$]::text[], array[$pb$Depósito de agua de solo 150 ml$pb$, $pb$Menos succión que el D20 Air Plus$pb$]::text[], $pb$[{"label":"Succión","value":"6000 Pa"},{"label":"Autovaciado","value":"Bolsa de 4 L"},{"label":"Autonomía","value":"285 min"},{"label":"Depósito de agua","value":"150 ml"},{"label":"Control","value":"App y voz"}]$pb$::jsonb);
