values ((select id from guides where slug = $pb$robots-aspiradores-menos-300$pb$), 4, $pb$Xiaomi Robot Vacuum S40C$pb$, $pb$Para el hogar conectado$pb$, $pb$Un robot sencillo y sin base de autovaciado, ideal si ya tienes Alexa o Google Home y quieres lanzarlo con la voz. Usa navegación láser LDS, aspira con 5000 Pa en cuatro modos y friega con tres niveles de agua. Su depósito de polvo de 520 ml y el de agua de 260 ml aguantan bien entre vaciados en un piso medio, y se gestiona con la app Xiaomi Home. Lo que pega: su autonomía es de 100 minutos y el vaciado es manual.$pb$, array[$pb$Compatible con Alexa y Google Home$pb$, $pb$Navegación láser LDS$pb$, $pb$Depósito de polvo de 520 ml$pb$]::text[], array[$pb$Sin autovaciado$pb$, $pb$Autonomía de 100 minutos$pb$]::text[], $pb$[{"label":"Succión","value":"5000 Pa"},{"label":"Navegación","value":"Láser LDS"},{"label":"Depósito de polvo","value":"520 ml"},{"label":"Depósito de agua","value":"260 ml"},{"label":"Autonomía","value":"100 min"}]$pb$::jsonb);
