values ((select id from guides where slug = $pb$robots-aspiradores-menos-300$pb$), 5, $pb$Lefant M1$pb$, $pb$Si quieres gastar lo mínimo$pb$, $pb$El más barato de la guía y, aun así, con navegación láser dToF que escanea hasta 15 metros y mapeo de varias plantas. Aspira con 5500 Pa, friega, permite bloquear zonas o programar por habitaciones desde la app y obedece a Alexa. Su batería anuncia hasta 200 minutos y vuelve solo a la base a recargar. Es una opción sensata para un primer robot o para un piso pequeño. Lo que pega: no tiene autovaciado y la marca es menos conocida que las demás de la lista.$pb$, array[$pb$El más barato de la guía$pb$, $pb$Navegación láser dToF y mapeo multinivel$pb$, $pb$Hasta 200 minutos de autonomía$pb$]::text[], array[$pb$Sin autovaciado$pb$, $pb$Marca menos conocida que las demás$pb$]::text[], $pb$[{"label":"Succión","value":"5500 Pa"},{"label":"Navegación","value":"Láser dToF"},{"label":"Autonomía","value":"200 min"},{"label":"Control","value":"App y voz (Alexa)"},{"label":"Superficies","value":"Madera y alfombra"}]$pb$::jsonb);
