values ((select id from guides where slug = $pb$juegos-de-mesa-familiares$pb$), 1, $pb$Carcassonne$pb$, $pb$Mejor en general$pb$, $pb$Un clásico de colocación de losetas que ganó el Spiel des Jahres en 2001 y que sigue siendo una buena puerta de entrada a los juegos modernos. Cada turno colocas una pieza y vas formando ciudades, caminos y monasterios, así que el tablero es diferente en cada partida. Admite de dos a cinco jugadores, lo que lo hace igual de bueno en pareja que en familia. Se aprende en una partida. Lo que pega: con niños pequeños la parte de contar puntos puede necesitar ayuda.$pb$, array[$pb$De 2 a 5 jugadores$pb$, $pb$Tablero distinto en cada partida$pb$, $pb$Reglas sencillas de explicar$pb$]::text[], array[$pb$El recuento de puntos lía al principio$pb$, $pb$Con cinco jugadores se alargan las esperas$pb$]::text[], $pb$[{"label":"Jugadores","value":"2 a 5"},{"label":"Tipo","value":"Colocación de losetas"},{"label":"Premio","value":"Spiel des Jahres 2001"},{"label":"Componentes","value":"Losetas, cartas, fichas y tablero"},{"label":"Idioma","value":"Castellano"}]$pb$::jsonb);
