values ((select i.id from guide_items i where i.guide_id = (select id from guides where slug = $pb$juegos-de-mesa-familiares$pb$) and i.position = 1), 'amazon', $pb$B00W5LCL8G$pb$, $pb$https://www.amazon.es/dp/B00W5LCL8G$pb$, 0);
insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$juegos-de-mesa-familiares$pb$), 2, $pb$Catan$pb$, $pb$Para los que quieren estrategia$pb$, $pb$Uno de los juegos de estrategia más conocidos, ganador del Spiel des Jahres en 1995. Los jugadores colonizan una isla, reúnen recursos y negocian entre ellos, así que es tan importante la estrategia como saber hablar en la mesa. Está pensado para tres o cuatro jugadores a partir de 10 años y cada partida dura alrededor de una hora. Encaja muy bien en familias con adolescentes. Lo que pega: no se puede jugar en pareja con el juego base y es largo para los más pequeños.$pb$, array[$pb$Mezcla estrategia y negociación$pb$, $pb$Muy rejugable$pb$, $pb$Ideal con adolescentes y adultos$pb$]::text[], array[$pb$Solo de 3 a 4 jugadores$pb$, $pb$Partidas de una hora o más$pb$]::text[], $pb$[{"label":"Jugadores","value":"3 a 4"},{"label":"Edad","value":"+10 años"},{"label":"Duración","value":"60-75 min"},{"label":"Género","value":"Estrategia"},{"label":"Premio","value":"Spiel des Jahres 1995"}]$pb$::jsonb);
