values ((select i.id from guide_items i where i.guide_id = (select id from guides where slug = $pb$juegos-de-mesa-familiares$pb$) and i.position = 2), 'amazon', $pb$B006CZ0LGA$pb$, $pb$https://www.amazon.es/dp/B006CZ0LGA$pb$, 0);
insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$juegos-de-mesa-familiares$pb$), 3, $pb$Dixit$pb$, $pb$Para los más creativos$pb$, $pb$Un juego de imaginación en el que el narrador elige una de sus cartas ilustradas, dice una frase o una palabra y el resto intenta despistar con cartas que encajen con esa pista. Esta edición renovada trae 84 cartas grandes, 8 diales de votación y 8 conejos de madera como marcadores. Admite de tres a ocho jugadores y la partida ronda la media hora. Funciona muy bien en mesas con edades mezcladas porque no hace falta saber nada. Lo que pega: con jugadores muy cuadriculados pierde gracia.$pb$, array[$pb$De 3 a 8 jugadores$pb$, $pb$No premia saber más, sino imaginar$pb$, $pb$Componentes de madera y cartas grandes$pb$]::text[], array[$pb$Necesita al menos tres jugadores$pb$, $pb$Con el tiempo las cartas se repiten sin expansiones$pb$]::text[], $pb$[{"label":"Jugadores","value":"3 a 8"},{"label":"Duración","value":"30 min"},{"label":"Cartas","value":"84 ilustradas"},{"label":"Componentes","value":"8 diales y 8 conejos de madera"},{"label":"Género","value":"Creativo"}]$pb$::jsonb);
