values ((select i.id from guide_items i where i.guide_id = (select id from guides where slug = $pb$juegos-de-mesa-familiares$pb$) and i.position = 3), 'amazon', $pb$B092R6L3T3$pb$, $pb$https://www.amazon.es/dp/B092R6L3T3$pb$, 0);
insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$juegos-de-mesa-familiares$pb$), 4, $pb$Trivial Pursuit Edición Familiar$pb$, $pb$Para mezclar edades$pb$, $pb$La versión del Trivial pensada para que niños y adultos jueguen en igualdad: trae tarjetas de preguntas separadas para cada grupo, en total 2400 preguntas repartidas en seis categorías. Se puede jugar uno contra uno o por equipos, y añade el desafío Duelo, en el que dos jugadores compiten a la vez por un quesito. Es una apuesta segura para las reuniones grandes de las fiestas. Lo que pega: cuando se repiten las preguntas pierde interés y alguien tiene que hacer de lector.$pb$, array[$pb$Tarjetas separadas para niños y adultos$pb$, $pb$2400 preguntas en 6 categorías$pb$, $pb$Se juega por equipos$pb$]::text[], array[$pb$Las preguntas acaban repitiéndose$pb$, $pb$Poco atractivo si no os gusta el formato concurso$pb$]::text[], $pb$[{"label":"Preguntas","value":"2400"},{"label":"Categorías","value":"6"},{"label":"Edad","value":"A partir de 8 años"},{"label":"Modo","value":"Individual o por equipos"},{"label":"Idioma","value":"Español"}]$pb$::jsonb);
