values ((select i.id from guide_items i where i.guide_id = (select id from guides where slug = $pb$juegos-de-mesa-familiares$pb$) and i.position = 4), 'amazon', $pb$B07D3Z1S7H$pb$, $pb$https://www.amazon.es/dp/B07D3Z1S7H$pb$, 0);
insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$juegos-de-mesa-familiares$pb$), 5, $pb$Código Secreto$pb$, $pb$Para grupos grandes$pb$, $pb$Un juego de palabras y deducción por equipos en el que todo gira en torno a dar pistas y adivinar qué quiso decir tu compañero. Admite de dos a ocho jugadores, las partidas duran unos quince minutos y se recomienda a partir de 8 años, así que cuesta poco enganchar a toda la familia y echar varias seguidas. Es además el más barato de la guía. Lo que pega: depende mucho del vocabulario, así que los más pequeños pueden quedarse atrás frente a los adultos.$pb$, array[$pb$De 2 a 8 jugadores por equipos$pb$, $pb$Partidas de 15 minutos$pb$, $pb$El más barato de la guía$pb$]::text[], array[$pb$Exige vocabulario, difícil para los más pequeños$pb$, $pb$En pareja pierde mucha gracia$pb$]::text[], $pb$[{"label":"Jugadores","value":"2 a 8"},{"label":"Duración","value":"15 min"},{"label":"Edad","value":"+8 años"},{"label":"Tipo","value":"Palabras y deducción por equipos"},{"label":"Edición","value":"Española"}]$pb$::jsonb);
