insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$relojes-y-pulseras-de-actividad-menos-100$pb$), 1, $pb$Huawei Watch Fit 4$pb$, $pb$Mejor en general$pb$, $pb$Un reloj fino y ligero, de 27 gramos y 9,5 mm, que reúne casi todo lo que se puede pedir en este rango. Tiene GPS integrado, barómetro para medir altitud y ascenso acumulado, pago sin contacto por NFC y una pantalla con brillo de hasta 2000 nits que se lee al sol. La batería llega a 10 días y con diez minutos de carga inalámbrica tienes para un día entero. Lo que pega: es el más caro de la guía y la ficha es poco clara sobre su resistencia al agua.$pb$, array[$pb$GPS integrado y barómetro$pb$, $pb$Pago sin contacto por NFC$pb$, $pb$Ligero y fino para llevar todo el día$pb$]::text[], array[$pb$El más caro de la guía$pb$, $pb$Ficha confusa sobre resistencia al agua$pb$]::text[], $pb$[{"label":"Peso","value":"27 g"},{"label":"Grosor","value":"9,5 mm"},{"label":"Batería","value":"Hasta 10 días"},{"label":"GPS","value":"Integrado"},{"label":"Extras","value":"Barómetro y NFC"}]$pb$::jsonb);
insert into guide_item_stores (guide_item_id, store, external_id, url, position)
values ((select i.id from guide_items i where i.guide_id = (select id from guides where slug = $pb$relojes-y-pulseras-de-actividad-menos-100$pb$) and i.position = 1), 'amazon', $pb$B0F2B1M9TB$pb$, $pb$https://www.amazon.es/dp/B0F2B1M9TB$pb$, 0);
insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$relojes-y-pulseras-de-actividad-menos-100$pb$), 2, $pb$Xiaomi Redmi Watch 6$pb$, $pb$Mejor relación calidad-precio$pb$, $pb$Una pantalla AMOLED grande, de 2,07 pulgadas, con biseles de 2 mm, en un cuerpo de aluminio de 9,9 mm. Su batería de 550 mAh anuncia hasta 24 días con uso ligero y tiene GPS con cinco sistemas de satélites para registrar rutas sin el móvil. Ofrece más de 150 modos deportivos y es resistente al agua hasta 50 metros. Lo que pega: la ficha no menciona NFC ni barómetro, y su tamaño puede resultar grande en muñecas finas.$pb$, array[$pb$Pantalla AMOLED de 2,07 pulgadas$pb$, $pb$Hasta 24 días de batería$pb$, $pb$GPS integrado y 150 modos deportivos$pb$]::text[], array[$pb$Sin NFC ni barómetro en la ficha$pb$, $pb$Grande para muñecas finas$pb$]::text[], $pb$[{"label":"Pantalla","value":"AMOLED 2,07\""},{"label":"Batería","value":"Hasta 24 días (550 mAh)"},{"label":"GPS","value":"GNSS L1, cinco sistemas"},{"label":"Resistencia al agua","value":"50 m"},{"label":"Caja","value":"Aluminio, 9,9 mm"}]$pb$::jsonb);
