values ((select i.id from guide_items i where i.guide_id = (select id from guides where slug = $pb$relojes-y-pulseras-de-actividad-menos-100$pb$) and i.position = 2), 'amazon', $pb$B0GQL9JZS7$pb$, $pb$https://www.amazon.es/dp/B0GQL9JZS7$pb$, 0);
insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$relojes-y-pulseras-de-actividad-menos-100$pb$), 3, $pb$CMF Watch 3 Pro$pb$, $pb$Para salir a correr$pb$, $pb$Pensado para quien corre o camina por ciudad y por senderos: su GPS de doble banda, con señales L1 y L5, posiciona más rápido y mantiene mejor la ruta entre edificios. La pantalla AMOLED de 1,43 pulgadas ofrece más de 120 esferas y modo siempre encendido, y permite hacer llamadas por Bluetooth. Su batería anuncia hasta 13 días con uso normal y unos 10 con uso intenso. Lo que pega: la ficha solo indica resistencia al agua hasta 3 metros, así que no lo elijas para nadar.$pb$, array[$pb$GPS de doble banda$pb$, $pb$Llamadas por Bluetooth$pb$, $pb$Más de 120 esferas y modo siempre encendido$pb$]::text[], array[$pb$No pensado para nadar$pb$, $pb$Batería más corta que la de la Smart Band 10$pb$]::text[], $pb$[{"label":"Pantalla","value":"AMOLED 1,43\""},{"label":"GPS","value":"Doble banda L1 + L5"},{"label":"Batería","value":"Hasta 13 días"},{"label":"Llamadas","value":"Bluetooth"},{"label":"Caja","value":"Aluminio"}]$pb$::jsonb);
