values ((select id from guides where slug = $pb$relojes-y-pulseras-de-actividad-menos-100$pb$), 4, $pb$Xiaomi Smart Band 10$pb$, $pb$Para nadar$pb$, $pb$Una pulsera con pantalla AMOLED de 1,72 pulgadas y caja de aluminio que destaca en la piscina: tiene modo profesional de natación, mide el pulso mientras nadas y es resistente al agua 5 ATM. Suma más de 150 modos deportivos, brújula, análisis del sueño con recomendaciones de recuperación y hasta 21 días de batería con carga rápida. Es una buena elección para quien quiere algo discreto que no moleste al dormir. Lo que pega: la ficha es ambigua sobre el GPS, así que no cuentes con registrar rutas sin el móvil.$pb$, array[$pb$Modo de natación con pulso en el agua$pb$, $pb$Hasta 21 días de batería$pb$, $pb$Pantalla AMOLED de 1,72 pulgadas$pb$]::text[], array[$pb$Ficha ambigua sobre el GPS$pb$, $pb$Pantalla pequeña para leer datos corriendo$pb$]::text[], $pb$[{"label":"Pantalla","value":"AMOLED 1,72\""},{"label":"Batería","value":"Hasta 21 días"},{"label":"Resistencia al agua","value":"5 ATM"},{"label":"Modos deportivos","value":"Más de 150"},{"label":"Caja","value":"Aluminio"}]$pb$::jsonb);
