insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$relojes-y-pulseras-de-actividad-menos-100$pb$), 5, $pb$Huawei Band 10$pb$, $pb$Si quieres gastar lo mínimo$pb$, $pb$La más barata de la lista y muy ligera, con solo 15 gramos y 8,99 mm de grosor, pensada para olvidarte de que la llevas. Su punto fuerte es el sueño: mide pulso, oxígeno en sangre, frecuencia respiratoria e irregularidades en la respiración mientras duermes. Tiene 100 modos de entrenamiento, reconocimiento de brazada para nadar y resistencia al agua de 50 metros. Lo que pega: no tiene GPS propio, usa el del móvil, y la ficha no indica la duración de la batería.$pb$, array[$pb$Muy ligera, 15 g$pb$, $pb$Seguimiento completo del sueño$pb$, $pb$Resistente al agua hasta 50 metros$pb$]::text[], array[$pb$Sin GPS propio$pb$, $pb$La ficha no detalla la batería$pb$]::text[], $pb$[{"label":"Peso","value":"15 g"},{"label":"Grosor","value":"8,99 mm"},{"label":"Sensores","value":"Pulso y SpO2"},{"label":"GPS","value":"Vía smartphone"},{"label":"Resistencia al agua","value":"50 m"}]$pb$::jsonb);
