values ((select id from guides where slug = $pb$gimnasio-en-casa-para-empezar$pb$), 1, $pb$Songmics mancuernas 2 en 1 de 20 kg$pb$, $pb$Para empezar con peso$pb$, $pb$El set con el que empezar a trabajar fuerza. Son dos mancuernas de 10 kg cada una que, con la barra de conexión de 20 cm incluida, se convierten en una barra de 20 kg para hacer peso muerto, remo o sentadillas. Los discos son de plástico relleno de cemento y arena, los mangos de 12 cm tienen moleteado antideslizante y los cierres de rosca en forma de estrella evitan que se aflojen. Lo que pega: los discos de arena son más voluminosos que los de hierro y, si progresas rápido, 20 kg se quedan cortos.$pb$, array[$pb$Se convierten en barra de 20 kg$pb$, $pb$Mango antideslizante y cierres de rosca$pb$, $pb$Discos recubiertos que no sueltan arena$pb$]::text[], array[$pb$Discos voluminosos$pb$, $pb$Con el tiempo necesitarás más peso$pb$]::text[], $pb$[{"label":"Peso total","value":"20 kg"},{"label":"Configuración","value":"2 x 10 kg o barra de 20 kg"},{"label":"Barra de conexión","value":"20 cm"},{"label":"Mango","value":"12 cm, moleteado"},{"label":"Discos","value":"PE con cemento y arena"}]$pb$::jsonb);
