values ((select i.id from guide_items i where i.guide_id = (select id from guides where slug = $pb$gimnasio-en-casa-para-empezar$pb$) and i.position = 1), 'amazon', $pb$B07GSVQGKF$pb$, $pb$https://www.amazon.es/dp/B07GSVQGKF$pb$, 0);
insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$gimnasio-en-casa-para-empezar$pb$), 2, $pb$Yoleo banco ajustable plegable$pb$, $pb$Para ganar ejercicios$pb$, $pb$La pieza que multiplica lo que puedes hacer con las mancuernas. El respaldo tiene siete posiciones, así que sirve en plano, inclinado y declinado para trabajar abdomen, espalda o piernas, con rodillos de espuma para sujetar los pies. Está tapizado en piel sintética fácil de limpiar, soporta hasta 300 kg según la ficha y se pliega para guardarlo. Pesa 10 kg. Lo que pega: desplegado ocupa más de un metro de largo, así que mide el hueco antes de comprarlo.$pb$, array[$pb$Respaldo con siete posiciones$pb$, $pb$Plegable para guardarlo$pb$, $pb$Carga máxima de 300 kg$pb$]::text[], array[$pb$Ocupa más de un metro desplegado$pb$, $pb$Pesa 10 kg, no es para moverlo a diario$pb$]::text[], $pb$[{"label":"Posiciones del respaldo","value":"7"},{"label":"Carga máxima","value":"300 kg"},{"label":"Medidas","value":"110,5 x 42,9 x 47 cm"},{"label":"Peso","value":"10 kg"},{"label":"Materiales","value":"Acero y piel sintética"}]$pb$::jsonb);
