values ((select i.id from guide_items i where i.guide_id = (select id from guides where slug = $pb$gimnasio-en-casa-para-empezar$pb$) and i.position = 2), 'amazon', $pb$B09V8BNQSZ$pb$, $pb$https://www.amazon.es/dp/B09V8BNQSZ$pb$, 0);
insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$gimnasio-en-casa-para-empezar$pb$), 3, $pb$Proiron esterilla 10 mm$pb$, $pb$Para el suelo$pb$, $pb$La base de cualquier rutina en casa: abdominales, flexiones, estiramientos, yoga o pilates. Mide 183 x 66 cm y tiene 10 mm de grosor de espuma de caucho de nitrilo, lo que amortigua bien en suelos duros. Lleva textura antideslizante por las dos caras, bordes reforzados contra desgarros, líneas de alineación para colocar manos y pies y una correa para transportarla. Pesa 1,1 kg. Lo que pega: con ese grosor es algo blanda para posturas de equilibrio de yoga, donde se prefiere una esterilla más fina.$pb$, array[$pb$10 mm de grosor, cómoda para las rodillas$pb$, $pb$Antideslizante por las dos caras$pb$, $pb$Incluye correa de transporte$pb$]::text[], array[$pb$Blanda para posturas de equilibrio$pb$, $pb$Abulta más enrollada que una esterilla fina$pb$]::text[], $pb$[{"label":"Medidas","value":"183 x 66 cm"},{"label":"Grosor","value":"10 mm"},{"label":"Material","value":"Caucho de nitrilo (NBR)"},{"label":"Peso","value":"1,1 kg"},{"label":"Extras","value":"Líneas de alineación y correa"}]$pb$::jsonb);
