values ((select i.id from guide_items i where i.guide_id = (select id from guides where slug = $pb$gimnasio-en-casa-para-empezar$pb$) and i.position = 3), 'amazon', $pb$B07BKQRWHT$pb$, $pb$https://www.amazon.es/dp/B07BKQRWHT$pb$, 0);
insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$gimnasio-en-casa-para-empezar$pb$), 4, $pb$Fokky bandas elásticas (set de 5)$pb$, $pb$Para entrenar en cualquier sitio$pb$, $pb$El complemento más barato de la guía y el que menos ocupa. Son cinco bandas de látex natural con cinco niveles de resistencia, de ligero a muy fuerte, diferenciadas por tonos de morado para saber cuál coges. Sirven para activar glúteos, sumar dificultad a sentadillas o trabajar hombros y brazos, y vienen con una bolsa para llevarlas de viaje. Son buenas para principiantes porque permiten ir subiendo de nivel. Lo que pega: al ser de látex no valen para personas con alergia y los colores parecidos pueden confundir al principio.$pb$, array[$pb$Cinco niveles de resistencia$pb$, $pb$Bolsa de transporte incluida$pb$, $pb$Ocupan muy poco$pb$]::text[], array[$pb$Látex natural: no aptas para alérgicos$pb$, $pb$Tonos de color parecidos entre sí$pb$]::text[], $pb$[{"label":"Unidades","value":"5 bandas"},{"label":"Resistencia","value":"4 a 30 lb"},{"label":"Material","value":"Látex natural"},{"label":"Medidas","value":"30 x 5 cm"},{"label":"Incluye","value":"Bolsa de transporte"}]$pb$::jsonb);
