insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$calefactores-bajo-consumo$pb$), 1, $pb$Philips serie 5000 torre 2000 W$pb$, $pb$Mejor en general$pb$, $pb$Para quien quiere un aparato que caliente bien un salón pequeño o un dormitorio grande y se pueda controlar desde el móvil. Ofrece potencia ajustable hasta 2000 W, oscilación de 60°, pantalla con la temperatura y conexión con la app Philips Air+, desde la que puedes programarlo aunque no estés en casa. Suma cinco medidas de seguridad, entre ellas antivuelco y apagado automático. La pega: lleva ventilador, así que no es tan silencioso como un radiador de aceite, y la app es otro paso más de configuración.$pb$, array[$pb$Control y programación desde la app Philips Air+$pb$, $pb$Oscilación de 60° para repartir el aire$pb$, $pb$Antivuelco, protección contra sobrecalentamiento y materiales ignífugos$pb$]::text[], array[$pb$Con ventilador, se oye más que un radiador de aceite$pb$, $pb$El calor se va pronto al apagarlo$pb$]::text[], $pb$[{"label":"Potencia","value":"Hasta 2000 W"},{"label":"Tipo","value":"Torre"},{"label":"Superficie recomendada","value":"Hasta 20 m²"},{"label":"Oscilación","value":"60°"},{"label":"Conectividad","value":"App Philips Air+"}]$pb$::jsonb);
