values ((select id from guides where slug = $pb$calefactores-bajo-consumo$pb$), 2, $pb$Dreo cerámico 1500 W$pb$, $pb$Para el despacho o el dormitorio$pb$, $pb$Un calefactor cerámico compacto para tenerlo junto al escritorio o en el dormitorio. Usa un elemento PTC de 1500 W, tiene termostato, modo ECO, modo solo ventilador y un temporizador de hasta 12 horas, así que puedes dejarlo programado y olvidarte. Incluye sensor de inclinación, bloqueo infantil y memoria de la última configuración, y su motor sin escobillas está pensado para hacer poco ruido. La pega: con 1500 W se queda corto para un salón, y como todo cerámico, el calor desaparece en cuanto lo apagas.$pb$, array[$pb$Temporizador de 12 horas y modo ECO$pb$, $pb$Bloqueo infantil y sensor de inclinación$pb$, $pb$Asa para moverlo de una habitación a otra$pb$]::text[], array[$pb$Potencia justa para estancias grandes$pb$, $pb$No guarda el calor tras apagarlo$pb$]::text[], $pb$[{"label":"Potencia","value":"1500 W"},{"label":"Elemento calefactor","value":"Cerámico (PTC)"},{"label":"Temporizador","value":"12 horas"},{"label":"Modos","value":"Potente, ECO y solo ventilador"},{"label":"Seguridad","value":"Antivuelco y bloqueo infantil"}]$pb$::jsonb);
