values ((select id from guides where slug = $pb$calefactores-bajo-consumo$pb$), 5, $pb$Orbegozo FH 5127 2000 W$pb$, $pb$Si quieres gastar lo mínimo$pb$, $pb$El más barato de la lista y el clásico calefactor de ventilador de toda la vida. Tiene dos posiciones de calor, 1000 y 2000 W, termostato ajustable y protección contra sobrecalentamiento, además de una función ventilador que sirve para refrescar en verano. Es la opción para un apoyo puntual: calentar el baño antes de la ducha o un cuarto que usas poco. La pega: no tiene temporizador, ni antivuelco indicado en la ficha, ni modo eco, y el ventilador se oye.$pb$, array[$pb$El más asequible de la guía$pb$, $pb$Dos potencias y termostato$pb$, $pb$Función ventilador para el verano$pb$]::text[], array[$pb$Sin temporizador ni modo eco$pb$, $pb$Ruido de ventilador perceptible$pb$]::text[], $pb$[{"label":"Potencia","value":"1000 / 2000 W"},{"label":"Tipo","value":"Calefactor de ventilador"},{"label":"Termostato","value":"Ajustable"},{"label":"Seguridad","value":"Protección contra sobrecalentamiento"},{"label":"Extras","value":"Función ventilador y luz de encendido"}]$pb$::jsonb);
