values ((select id from guides where slug = $pb$ssd-nvme-y-discos-externos$pb$), 1, $pb$Kingston NV3 1 TB PCIe 4.0$pb$, $pb$Para acelerar un PC moderno$pb$, $pb$La opción para quien tiene un portátil o un PC con ranura M.2 compatible con PCIe 4.0 y quiere aprovecharla. Anuncia hasta 6000 MB/s de lectura y 5000 MB/s de escritura, en formato M.2 2280, el más habitual en placas base y portátiles. Es buena opción para el disco principal, donde se nota más el arranque y la carga de programas y juegos. La pega: en equipos con ranura PCIe 3.0 no alcanza esa velocidad, y la ficha no detalla los años de garantía.$pb$, array[$pb$Hasta 6000 MB/s de lectura y 5000 MB/s de escritura$pb$, $pb$Formato M.2 2280, el más extendido$pb$, $pb$Encaja en portátiles finos y PC compactos$pb$]::text[], array[$pb$En ranuras PCIe 3.0 rinde como un Gen3$pb$, $pb$La ficha no indica la garantía$pb$]::text[], $pb$[{"label":"Capacidad","value":"1 TB"},{"label":"Interfaz","value":"NVMe PCIe 4.0 x4"},{"label":"Formato","value":"M.2 2280"},{"label":"Lectura","value":"Hasta 6000 MB/s"},{"label":"Escritura","value":"Hasta 5000 MB/s"}]$pb$::jsonb);
