insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$ssd-nvme-y-discos-externos$pb$), 2, $pb$PNY CS1030 1 TB PCIe 3.0$pb$, $pb$Para ampliar el portátil$pb$, $pb$Pensado para dar una segunda vida a un portátil de hace unos años que aún tiene disco SATA o un SSD pequeño. Es un NVMe PCIe Gen3 x4 en formato M.2 2280 con hasta 2100 MB/s de lectura y 1700 MB/s de escritura, de sobra para notar el cambio frente a un disco duro tradicional. La marca destaca su bajo consumo, útil en portátiles, y ofrece cinco años de garantía o hasta el límite de escritura (TBW). La pega: en un equipo con PCIe 4.0 se queda lejos del Kingston.$pb$, array[$pb$Garantía de cinco años o TBW$pb$, $pb$Bajo consumo, pensado para portátiles$pb$, $pb$Gran salto frente a un disco SATA o mecánico$pb$]::text[], array[$pb$Más lento que los modelos PCIe 4.0$pb$, $pb$La garantía acaba antes si llegas al límite de escritura (TBW)$pb$]::text[], $pb$[{"label":"Capacidad","value":"1 TB"},{"label":"Interfaz","value":"NVMe PCIe 3.0 x4"},{"label":"Formato","value":"M.2 2280"},{"label":"Lectura","value":"Hasta 2100 MB/s"},{"label":"Escritura","value":"Hasta 1700 MB/s"},{"label":"Garantía","value":"5 años o TBW"}]$pb$::jsonb);
