values ((select i.id from guide_items i where i.guide_id = (select id from guides where slug = $pb$ssd-nvme-y-discos-externos$pb$) and i.position = 2), 'amazon', $pb$B08M49JGKB$pb$, $pb$https://www.amazon.es/dp/B08M49JGKB$pb$, 0);
insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$ssd-nvme-y-discos-externos$pb$), 3, $pb$WD My Passport 2 TB$pb$, $pb$Para copias de seguridad$pb$, $pb$El disco externo para quien quiere hacer copias de seguridad sin pensar en ellas. Incluye software para programarlas de forma automática, protección con contraseña y cifrado por hardware AES de 256 bits, útil si guardas documentos personales o de trabajo. Se conecta por USB 3.2 Gen 1 (5 Gb/s), trae el cable en la caja, viene formateado para Windows, ChromeOS y macOS y tiene tres años de garantía. La pega: es un disco mecánico de 5400 rpm, así que copiar grandes volúmenes lleva su tiempo.$pb$, array[$pb$Software de copia de seguridad programable$pb$, $pb$Contraseña y cifrado AES de 256 bits por hardware$pb$, $pb$Tres años de garantía$pb$]::text[], array[$pb$Disco mecánico, más lento que un SSD$pb$, $pb$Hay que instalar software para cifrar$pb$]::text[], $pb$[{"label":"Capacidad","value":"2 TB"},{"label":"Conexión","value":"USB 3.2 Gen 1 (5 Gb/s)"},{"label":"Tipo","value":"Disco duro de 2,5\" a 5400 rpm"},{"label":"Seguridad","value":"Contraseña y cifrado AES 256 bits"},{"label":"Garantía","value":"3 años"}]$pb$::jsonb);
