values ((select i.id from guide_items i where i.guide_id = (select id from guides where slug = $pb$ssd-nvme-y-discos-externos$pb$) and i.position = 3), 'amazon', $pb$B07VTFN6HM$pb$, $pb$https://www.amazon.es/dp/B07VTFN6HM$pb$, 0);
