values ((select id from guides where slug = $pb$ssd-nvme-y-discos-externos$pb$), 4, $pb$LaCie Rugged Mini 2 TB$pb$, $pb$Para llevar en la mochila$pb$, $pb$Para quien mueve sus archivos de un sitio a otro y no quiere preocuparse por un golpe. Según la ficha, resiste caídas de hasta 1,2 m y presiones de hasta 1000 kg, e incluye software de respaldo automático con cifrado AES de 256 bits. Suma dos años de garantía y dos años de servicio de recuperación de datos, algo poco habitual. La pega: incluye cable Micro B a USB-C, pero no el de USB-A, y su velocidad es la de un disco mecánico.$pb$, array[$pb$Resiste caídas de hasta 1,2 m$pb$, $pb$Servicio de recuperación de datos durante dos años$pb$, $pb$Cifrado AES de 256 bits y copias automáticas$pb$]::text[], array[$pb$No incluye cable USB-A$pb$, $pb$Conector Micro B en el disco$pb$]::text[], $pb$[{"label":"Capacidad","value":"2 TB"},{"label":"Conexión","value":"USB-C (cable Micro B a USB-C)"},{"label":"Resistencia","value":"Caídas de 1,2 m y 1000 kg de presión"},{"label":"Seguridad","value":"Cifrado AES 256 bits"},{"label":"Garantía","value":"2 años + recuperación de datos"}]$pb$::jsonb);
