values ((select id from guides where slug = $pb$cafeteras-capsulas-y-espresso-menos-150$pb$), 1, $pb$Nespresso Citiz EN167 de De'Longhi$pb$, $pb$Mejor en general$pb$, $pb$Para quien quiere un espresso consistente cada mañana y no renunciar al café con leche en taza grande. Tiene bomba de 19 bares, calentamiento Thermoblock y cantidad de café automática y programable. Su punto fuerte es el soporte de tazas abatible con dos posiciones, una para espresso y otra para vaso alto. Viene con 14 cápsulas para empezar. La pega: es la más cara de la guía y no tiene espumador de leche.$pb$, array[$pb$Soporte de tazas abatible con dos alturas$pb$, $pb$Cantidad de café programable$pb$, $pb$Incluye 14 cápsulas para empezar$pb$]::text[], array[$pb$La más cara de la lista$pb$, $pb$Sin espumador de leche$pb$]::text[], $pb$[{"label":"Sistema","value":"Nespresso Original"},{"label":"Presión","value":"19 bares"},{"label":"Calentamiento","value":"Thermoblock"},{"label":"Potencia","value":"1260 W"},{"label":"Soporte de tazas","value":"Abatible, dos posiciones"}]$pb$::jsonb);
