insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$cafeteras-capsulas-y-espresso-menos-150$pb$), 2, $pb$Nespresso Inissia EN80 de De'Longhi$pb$, $pb$Mejor relación calidad-precio$pb$, $pb$La forma más directa de entrar en el sistema Nespresso. Está lista en unos 25 segundos gracias al Thermoblock, tiene bomba de 19 bares, cantidad de café programable con Flow Stop y expulsa la cápsula usada sola. Se apaga a los nueve minutos sin uso y su depósito extraíble es de 0,7 litros. Es ideal para una o dos personas que toman sobre todo espresso o café solo. La pega: el depósito se queda corto si sois muchos en casa y no tiene espumador.$pb$, array[$pb$Lista en unos 25 segundos$pb$, $pb$Cantidad de café programable$pb$, $pb$Expulsión automática de cápsulas$pb$]::text[], array[$pb$Depósito de solo 0,7 litros$pb$, $pb$Sin espumador de leche$pb$]::text[], $pb$[{"label":"Sistema","value":"Nespresso Original"},{"label":"Presión","value":"19 bares"},{"label":"Depósito","value":"0,7 L"},{"label":"Calentamiento","value":"Thermoblock (25 s)"},{"label":"Autoapagado","value":"9 minutos"}]$pb$::jsonb);
