values ((select id from guides where slug = $pb$cafeteras-capsulas-y-espresso-menos-150$pb$), 3, $pb$Dolce Gusto Mini Me 2 de De'Longhi$pb$, $pb$Para bebidas frías y con leche$pb$, $pb$La opción si en casa se toman cafés con leche, cafés largos o bebidas frías en verano. Funciona en modo frío y caliente, tiene bomba de 15 bares y un control LED con el que ajustas la cantidad de cada bebida. Su depósito extraíble es de 0,8 litros, se apaga a los cinco minutos sin uso y este pack incluye tres cajas de cápsulas para empezar. La pega: las cápsulas compatibles de otras marcas son menos habituales que en Nespresso.$pb$, array[$pb$Prepara bebidas frías y calientes$pb$, $pb$Incluye tres packs de cápsulas$pb$, $pb$Depósito de 0,8 litros$pb$]::text[], array[$pb$Menos cápsulas compatibles en el súper$pb$, $pb$Se apaga a los cinco minutos, algo pronto si preparas varias$pb$]::text[], $pb$[{"label":"Sistema","value":"Dolce Gusto"},{"label":"Presión","value":"15 bares"},{"label":"Depósito","value":"0,8 L"},{"label":"Control","value":"LED, cantidad ajustable"},{"label":"Autoapagado","value":"5 minutos"}]$pb$::jsonb);
