values ((select id from guides where slug = $pb$cafeteras-capsulas-y-espresso-menos-150$pb$), 5, $pb$Bosch Tassimo Style TAS113E$pb$, $pb$Si quieres gastar lo mínimo$pb$, $pb$La más barata de la lista y una de las más estrechas: mide unos 17 cm de ancho, así que cabe en cocinas pequeñas. Funciona con un solo botón y la tecnología Intellibrew ajusta la preparación a cada cápsula, con acceso a hasta 70 bebidas distintas del catálogo Tassimo. Tiene depósito extraíble y clasificación energética A+. La pega: no es una espresso de bomba como las demás, y el catálogo de cápsulas depende casi por completo de la marca.$pb$, array[$pb$Ancho de solo unos 17 cm$pb$, $pb$Funcionamiento con un solo botón$pb$, $pb$Hasta 70 bebidas distintas$pb$]::text[], array[$pb$No prepara espresso a alta presión$pb$, $pb$Pocas cápsulas de otras marcas$pb$]::text[], $pb$[{"label":"Sistema","value":"Tassimo"},{"label":"Potencia","value":"1400 W"},{"label":"Medidas","value":"32 × 17,1 × 26,5 cm"},{"label":"Peso","value":"2,5 kg"},{"label":"Clase energética","value":"A+"}]$pb$::jsonb);
