values ((select id from guides where slug = $pb$secadores-y-planchas-de-pelo-menos-80$pb$), 1, $pb$Remington PROluxe secador 2400 W$pb$, $pb$Mejor secador$pb$, $pb$El secador más completo de la guía, pensado para quien se seca el pelo a diario y quiere variedad de acabados. Tiene motor AC de 2400 W, acondicionador iónico, tecnología OPTIheat para repartir el calor, botón de aire frío y siete combinaciones de ajustes. Incluye tres accesorios: concentrador de 7 mm, concentrador híbrido y difusor, así que sirve tanto para alisar como para rizos. El cable mide 3 metros. La pega: con motor AC pesa más que un secador compacto.$pb$, array[$pb$Motor AC de 2400 W$pb$, $pb$Tres accesorios, incluido difusor$pb$, $pb$Cable de 3 metros y anilla para colgar$pb$]::text[], array[$pb$Más pesado que un secador de viaje$pb$, $pb$Más voluminoso para guardar$pb$]::text[], $pb$[{"label":"Potencia","value":"2400 W"},{"label":"Motor","value":"AC"},{"label":"Ajustes","value":"7 (2 velocidades)"},{"label":"Accesorios","value":"2 concentradores y difusor"},{"label":"Cable","value":"3 m"}]$pb$::jsonb);
