values ((select id from guides where slug = $pb$secadores-y-planchas-de-pelo-menos-80$pb$), 2, $pb$Cecotec Bamba IoniCare 5200 Aura$pb$, $pb$Si quieres gastar lo mínimo$pb$, $pb$El más barato de la lista y una opción muy sensata para un uso normal. Tiene motor de 2300 W, función iónica, ajuste de temperatura y velocidad, aire frío y tecnología Hair Care para no sobrecalentar el pelo. Trae boquilla de precisión y difusor, y su rejilla trasera se quita para limpiar el filtro con facilidad. La pega: el cable se queda en 1,8 metros, que puede quedarse corto si el enchufe está lejos del espejo.$pb$, array[$pb$El más asequible de la guía$pb$, $pb$Incluye boquilla y difusor$pb$, $pb$Filtro trasero extraíble$pb$]::text[], array[$pb$Cable de solo 1,8 metros$pb$, $pb$Menos ajustes que el Remington$pb$]::text[], $pb$[{"label":"Potencia","value":"2300 W"},{"label":"Ajustes","value":"5 (2 velocidades)"},{"label":"Accesorios","value":"Boquilla de precisión y difusor"},{"label":"Cable","value":"1,8 m"},{"label":"Función","value":"Iónica y aire frío"}]$pb$::jsonb);
