values ((select i.id from guide_items i where i.guide_id = (select id from guides where slug = $pb$secadores-y-planchas-de-pelo-menos-80$pb$) and i.position = 2), 'amazon', $pb$B07ZRR8LJF$pb$, $pb$https://www.amazon.es/dp/B07ZRR8LJF$pb$, 0);
insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$secadores-y-planchas-de-pelo-menos-80$pb$), 3, $pb$Rowenta Thermoglide SF5180$pb$, $pb$Mejor plancha$pb$, $pb$La plancha más equilibrada de la guía para quien la usa a menudo. Sus placas flotantes con revestimiento de titanio se adaptan al mechón, tiene función iónica y cinco ajustes entre 150 y 230 °C, con un modo cuidado a 170 °C. El diseño redondeado permite hacer ondas, el cable gira 360° y tiene bloqueo para guardarla. Calienta en unos 30 segundos y la marca indica 15 años de reparabilidad. La pega: tarda algo más en calentar que la Remington.$pb$, array[$pb$Placas flotantes de titanio$pb$, $pb$Modo cuidado a 170 °C$pb$, $pb$Cable giratorio y bloqueo para guardarla$pb$]::text[], array[$pb$Calienta en 30 segundos, no al instante$pb$, $pb$Solo cinco niveles de temperatura$pb$]::text[], $pb$[{"label":"Placas","value":"Flotantes, revestimiento de titanio"},{"label":"Temperatura","value":"150–230 °C (5 ajustes)"},{"label":"Calentamiento","value":"30 s"},{"label":"Función","value":"Iónica"},{"label":"Cable","value":"Giratorio 360°"}]$pb$::jsonb);
