values ((select i.id from guide_items i where i.guide_id = (select id from guides where slug = $pb$secadores-y-planchas-de-pelo-menos-80$pb$) and i.position = 3), 'amazon', $pb$B0FX5GHMPF$pb$, $pb$https://www.amazon.es/dp/B0FX5GHMPF$pb$, 0);
insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$secadores-y-planchas-de-pelo-menos-80$pb$), 4, $pb$BaByliss Super Smooth 235 ST393E$pb$, $pb$Para pelo grueso o rebelde$pb$, $pb$Si tu pelo es grueso o muy rizado y te cuesta alisarlo, esta plancha llega hasta 235 °C, algo más que las demás. Tiene placas de cerámica con titanio, función iónica antiencrespamiento y seis temperaturas desde 140 °C, así que también puedes bajarla para pelo fino o teñido. Incluye una alfombrilla resistente al calor para apoyarla. La pega: la ficha no incluye funda de viaje y la temperatura máxima no es recomendable para todos los cabellos.$pb$, array[$pb$Llega hasta 235 °C$pb$, $pb$Seis temperaturas desde 140 °C$pb$, $pb$Alfombrilla térmica incluida$pb$]::text[], array[$pb$La ficha no incluye funda de viaje$pb$, $pb$Las temperaturas altas exigen protector térmico$pb$]::text[], $pb$[{"label":"Placas","value":"Cerámica con titanio"},{"label":"Temperatura","value":"140–235 °C (6 ajustes)"},{"label":"Función","value":"Iónica"},{"label":"Incluye","value":"Alfombrilla térmica"}]$pb$::jsonb);
