values ((select id from guides where slug = $pb$secadores-y-planchas-de-pelo-menos-80$pb$), 5, $pb$Remington PROluxe plancha S9100$pb$, $pb$Para viajar$pb$, $pb$La compañera ideal de la maleta. Tiene voltaje universal, cierre y funda incluida, así que puedes usarla y guardarla fuera de casa sin preocuparte. Calienta en unos 10 segundos, ofrece nueve posiciones entre 150 y 230 °C y sus placas de cerámica cuentan con la tecnología OPTIheat de Remington. Además, se apaga sola. La pega: la ficha no indica placas flotantes, así que en pelo muy grueso puede requerir alguna pasada más.$pb$, array[$pb$Voltaje universal y funda incluida$pb$, $pb$Calienta en unos 10 segundos$pb$, $pb$Nueve niveles de temperatura y apagado automático$pb$]::text[], array[$pb$Sin placas flotantes indicadas en la ficha$pb$, $pb$Sin función iónica indicada$pb$]::text[], $pb$[{"label":"Placas","value":"Cerámica"},{"label":"Temperatura","value":"150–230 °C (9 posiciones)"},{"label":"Calentamiento","value":"10 s"},{"label":"Voltaje","value":"Universal"},{"label":"Incluye","value":"Funda y cierre"}]$pb$::jsonb);
