insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$afeitadoras-y-recortadoras-de-barba$pb$), 1, $pb$Braun Series 7 BT7525$pb$, $pb$Mejor en general$pb$, $pb$Para quien lleva barba y quiere controlarla al detalle. Ofrece 40 ajustes de longitud en pasos de 0,5 mm con rueda de ajuste y bloqueo, lámina de corte ProBlade y tecnología AutoSense para mantener el corte uniforme. Incluye cabezal de afeitado para perfilar líneas, dos peines y plantilla para la barba. Es resistente al agua y su batería de litio da hasta 120 minutos de uso sin cable. La pega: si solo quieres afeitarte a cero, no es la herramienta adecuada.$pb$, array[$pb$40 longitudes en pasos de 0,5 mm$pb$, $pb$Hasta 120 minutos de autonomía$pb$, $pb$Cabezal de afeitado para perfilar$pb$]::text[], array[$pb$No sustituye a una afeitadora para el apurado diario$pb$, $pb$Muchos accesorios que guardar$pb$]::text[], $pb$[{"label":"Tipo","value":"Recortadora de barba"},{"label":"Longitudes","value":"40 (pasos de 0,5 mm)"},{"label":"Autonomía","value":"Hasta 120 min"},{"label":"Batería","value":"Iones de litio"},{"label":"Resistente al agua","value":"Sí"}]$pb$::jsonb);
