values ((select i.id from guide_items i where i.guide_id = (select id from guides where slug = $pb$afeitadoras-y-recortadoras-de-barba$pb$) and i.position = 1), 'amazon', $pb$B0DQWYGX7M$pb$, $pb$https://www.amazon.es/dp/B0DQWYGX7M$pb$, 0);
insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$afeitadoras-y-recortadoras-de-barba$pb$), 2, $pb$Philips Serie 5000 S5465$pb$, $pb$Para afeitarte a diario$pb$, $pb$La opción si te afeitas cada día y quieres la cara lisa. Es una afeitadora rotativa con 27 cuchillas autoafilables y cabezales flexibles que giran 360 grados para seguir el contorno de la cara. Se usa en seco o en húmedo, se limpia abriendo el cabezal con un botón y enjuagando, e incluye un recortador de clic para bigote y patillas. Con una hora de carga da 50 minutos de uso, y una carga rápida de cinco minutos basta para un afeitado. La pega: el recortador incluido no sirve para mantener una barba.$pb$, array[$pb$Cabezales flexibles 360 grados$pb$, $pb$Uso en seco o en húmedo$pb$, $pb$Carga rápida de cinco minutos para un afeitado$pb$]::text[], array[$pb$No mantiene barba a una longitud fija$pb$, $pb$Los cabezales rotativos requieren limpieza frecuente$pb$]::text[], $pb$[{"label":"Tipo","value":"Afeitadora rotativa"},{"label":"Cuchillas","value":"27 autoafilables"},{"label":"Autonomía","value":"50 min"},{"label":"Carga","value":"1 h (rápida de 5 min)"},{"label":"Incluye","value":"Recortador de clic"}]$pb$::jsonb);
