values ((select i.id from guide_items i where i.guide_id = (select id from guides where slug = $pb$afeitadoras-y-recortadoras-de-barba$pb$) and i.position = 2), 'amazon', $pb$B0CFY7R1GX$pb$, $pb$https://www.amazon.es/dp/B0CFY7R1GX$pb$, 0);
insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$afeitadoras-y-recortadoras-de-barba$pb$), 3, $pb$Philips OneBlade 360 QP2724$pb$, $pb$Para barba de pocos días$pb$, $pb$Para quien alterna entre cara lisa y barba incipiente y no quiere dos aparatos. La cuchilla 360 se inclina en todas las direcciones, recorta, perfila con su doble cara y afeita cualquier longitud de vello sin apurar tanto como una afeitadora. Trae tres peines de 1, 3 y 5 mm, dos cuchillas y funda. Es resistente al agua y su batería da 45 minutos. La pega: las cuchillas se cambian cada pocos meses y el adaptador de corriente no viene incluido.$pb$, array[$pb$Afeita, recorta y perfila con una sola herramienta$pb$, $pb$Incluye dos cuchillas y tres peines$pb$, $pb$Uso en seco, en húmedo o en la ducha$pb$]::text[], array[$pb$Adaptador de corriente no incluido$pb$, $pb$Recambios de cuchilla cada pocos meses$pb$]::text[], $pb$[{"label":"Tipo","value":"OneBlade (afeita y recorta)"},{"label":"Peines","value":"1, 3 y 5 mm"},{"label":"Autonomía","value":"45 min"},{"label":"Batería","value":"Ni-MH"},{"label":"Duración de la cuchilla","value":"Hasta 4 meses"}]$pb$::jsonb);
