values ((select i.id from guide_items i where i.guide_id = (select id from guides where slug = $pb$afeitadoras-y-recortadoras-de-barba$pb$) and i.position = 3), 'amazon', $pb$B0DCFP3Z14$pb$, $pb$https://www.amazon.es/dp/B0DCFP3Z14$pb$, 0);
