values ((select id from guides where slug = $pb$afeitadoras-y-recortadoras-de-barba$pb$), 4, $pb$Panasonic ER-SB40$pb$, $pb$Para perfilar con precisión$pb$, $pb$Una recortadora pensada para quien mantiene la barba corta y quiere un corte muy uniforme. Tiene motor lineal que mantiene la potencia con cualquier nivel de batería, cuchillas anchas que levantan el vello rizado o plano y 20 longitudes entre 0,5 y 10 mm en pasos de 0,5 mm. Es resistente al agua IPX7, se carga en una hora para 60 minutos de uso, tiene indicador LED y bloqueo para viajes. La pega: es la más cara de la guía y no llega a longitudes de barba larga.$pb$, array[$pb$Motor lineal con potencia constante$pb$, $pb$20 longitudes en pasos de 0,5 mm$pb$, $pb$Bloqueo para viajes e indicador de batería$pb$]::text[], array[$pb$La más cara de la lista$pb$, $pb$Máximo de 10 mm, corto para barbas largas$pb$]::text[], $pb$[{"label":"Tipo","value":"Recortadora de barba"},{"label":"Longitudes","value":"20 (0,5–10 mm)"},{"label":"Autonomía","value":"60 min"},{"label":"Carga","value":"1 h"},{"label":"Resistencia al agua","value":"IPX7"}]$pb$::jsonb);
