insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$afeitadoras-y-recortadoras-de-barba$pb$), 5, $pb$Braun Series 3 AIO3545$pb$, $pb$Si quieres gastar lo mínimo$pb$, $pb$La más barata de la lista y la única pensada también para cortar el pelo. Es un kit 8 en 1 con accesorios para la barba y la cabeza, 14 longitudes entre 3 y 21 mm, cabezales lavables, cepillo de limpieza y funda. Su batería da 50 minutos sin cable. Es una buena opción para un primer kit o para regalar. La pega: no baja de 3 mm, así que no sirve para barba de un día ni para perfilar con mucho detalle.$pb$, array[$pb$Kit 8 en 1 para barba y pelo$pb$, $pb$Cabezales lavables y funda$pb$, $pb$Longitudes hasta 21 mm$pb$]::text[], array[$pb$Longitud mínima de 3 mm$pb$, $pb$Menos precisión que la Series 7$pb$]::text[], $pb$[{"label":"Tipo","value":"Kit recortadora 8 en 1"},{"label":"Longitudes","value":"14 (3–21 mm)"},{"label":"Autonomía","value":"50 min"},{"label":"Incluye","value":"Peines, cepillo y funda"}]$pb$::jsonb);
