insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$monitores-27-teletrabajo$pb$), 1, $pb$Philips 27E1N1600AE QHD USB-C$pb$, $pb$Mejor en general$pb$, $pb$El monitor para quien trabaja con portátil y quiere un escritorio ordenado. Con un solo cable USB-C ves la imagen, transfieres datos y cargas el portátil con hasta 65 W, y su hub USB con dos puertos te permite enchufar teclado y ratón al monitor. Es QHD, tiene 350 cd/m² de brillo, contraste de 1500:1, pantalla mate, FreeSync y modos sin parpadeo y de luz azul reducida. La pega: es el más caro de la guía y su HDMI es 1.4.$pb$, array[$pb$USB-C con carga de hasta 65 W$pb$, $pb$Hub USB para teclado y ratón$pb$, $pb$Resolución QHD y 350 cd/m² de brillo$pb$]::text[], array[$pb$El más caro de la lista$pb$, $pb$HDMI 1.4, no 2.0$pb$]::text[], $pb$[{"label":"Tamaño","value":"27\""},{"label":"Resolución","value":"QHD"},{"label":"Brillo","value":"350 cd/m²"},{"label":"Contraste","value":"1500:1"},{"label":"Conexiones","value":"HDMI 1.4, USB-C (65 W) y hub USB"}]$pb$::jsonb);
insert into guide_item_stores (guide_item_id, store, external_id, url, position)
values ((select i.id from guide_items i where i.guide_id = (select id from guides where slug = $pb$monitores-27-teletrabajo$pb$) and i.position = 1), 'amazon', $pb$B0D1RCQVKN$pb$, $pb$https://www.amazon.es/dp/B0D1RCQVKN$pb$, 0);
insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$monitores-27-teletrabajo$pb$), 2, $pb$Philips 27E2N1500L QHD$pb$, $pb$Mejor relación calidad-precio$pb$, $pb$Para quien quiere la nitidez de la resolución 2560 × 1440 sin pagar por el USB-C. Es un panel IPS de 27 pulgadas con pantalla mate, compatible con HDR10, sin parpadeo y con sincronización adaptativa. Tiene entrada HDMI y DisplayPort, así que encaja con la mayoría de ordenadores de sobremesa y portátiles. Su frecuencia de 75 Hz es de sobra para trabajar y estudiar. La pega: no carga el portátil ni tiene hub USB, y para juegos rápidos se queda corto.$pb$, array[$pb$Resolución QHD a buen precio$pb$, $pb$HDMI y DisplayPort$pb$, $pb$Pantalla mate y sin parpadeo$pb$]::text[], array[$pb$Sin USB-C ni hub USB$pb$, $pb$75 Hz, justo para juegos$pb$]::text[], $pb$[{"label":"Tamaño","value":"27\""},{"label":"Resolución","value":"2560 × 1440"},{"label":"Frecuencia","value":"75 Hz"},{"label":"Contraste","value":"1000:1"},{"label":"HDR","value":"HDR10"}]$pb$::jsonb);
insert into guide_item_stores (guide_item_id, store, external_id, url, position)
values ((select i.id from guide_items i where i.guide_id = (select id from guides where slug = $pb$monitores-27-teletrabajo$pb$) and i.position = 2), 'amazon', $pb$B0F9YSJJG2$pb$, $pb$https://www.amazon.es/dp/B0F9YSJJG2$pb$, 0);
insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$monitores-27-teletrabajo$pb$), 3, $pb$ASUS VY279HGR$pb$, $pb$Para cuidar la vista$pb$, $pb$Pensado para jornadas largas delante de la pantalla. Su paquete Eye Care Plus incluye un recordatorio de descanso para gestionar el tiempo de pantalla y un modo que ayuda a distinguir colores a personas con alteraciones en su percepción. Es un IPS Full HD de 27 pulgadas a 120 Hz con pantalla mate, contraste de 2000:1 y Adaptive Sync, y los marcos y botones llevan un tratamiento antibacteriano. La pega: la resolución Full HD a 27 pulgadas muestra el texto menos nítido que un QHD.$pb$, array[$pb$Recordatorio de descanso integrado$pb$, $pb$120 Hz y contraste de 2000:1$pb$, $pb$Tratamiento antibacteriano en marcos y botones$pb$]::text[], array[$pb$Full HD, menos espacio útil que un QHD$pb$, $pb$La ficha no detalla las conexiones$pb$]::text[], $pb$[{"label":"Tamaño","value":"27\""},{"label":"Resolución","value":"Full HD"},{"label":"Frecuencia","value":"120 Hz"},{"label":"Contraste","value":"2000:1"},{"label":"Brillo","value":"250 cd/m²"}]$pb$::jsonb);
