values ((select id from guides where slug = $pb$aspiradores-escoba-sin-cable-menos-200$pb$), 2, $pb$Ultenic U18Pro 55 kPa$pb$, $pb$Más autonomía$pb$, $pb$Para casas grandes o para quien no quiere estar pendiente de la batería. Anuncia 80 minutos de autonomía y una pantalla LED que muestra los minutos que quedan en tiempo real. Tiene tres niveles de potencia, depósito de 1,6 litros, filtro HEPA y cepillo anti-enredos pensado para pelo de mascota. Se sostiene solo y se carga en su soporte de pared. No friega, y como en todos, la autonomía máxima es en el modo más bajo.$pb$, array[$pb$80 minutos anunciados con contador en pantalla$pb$, $pb$Depósito de 1,6 L$pb$, $pb$Autoportante y con soporte de carga a la pared$pb$]::text[], array[$pb$En potencia máxima la autonomía baja bastante$pb$, $pb$Marca menos conocida que Rowenta$pb$]::text[], $pb$[{"label":"Autonomía","value":"Hasta 80 min"},{"label":"Succión","value":"55 kPa"},{"label":"Depósito","value":"1,6 L"},{"label":"Ruido","value":"62 dB"},{"label":"Niveles de potencia","value":"3"}]$pb$::jsonb);
