insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$aspiradores-escoba-sin-cable-menos-200$pb$), 3, $pb$Proscenic P20 aspira y friega$pb$, $pb$Aspira y friega en una pasada$pb$, $pb$Si en casa domina la baldosa o la tarima, este Proscenic aspira y friega a la vez gracias a un depósito de agua externo. Su ficha indica motor sin escobillas de 680 W, 70 kPa de succión y un sensor que ajusta la potencia según la suciedad. Es autoportante, la boquilla se inclina 180° para colarse bajo la cama y tiene luz verde para ver el polvo. Los 70 minutos se anuncian sin el cepillo motorizado, así que con él durará menos.$pb$, array[$pb$Aspira y friega a la vez$pb$, $pb$Potencia autoajustable con sensor de suciedad$pb$, $pb$59 dB declarados, de los más silenciosos$pb$]::text[], array[$pb$Los 70 minutos son sin cepillo motorizado$pb$, $pb$Hay que limpiar también el depósito de agua$pb$]::text[], $pb$[{"label":"Succión","value":"70 kPa"},{"label":"Motor","value":"680 W sin escobillas"},{"label":"Autonomía","value":"Hasta 70 min"},{"label":"Depósito","value":"1,5 L"},{"label":"Ruido","value":"59 dB"}]$pb$::jsonb);
