values ((select i.id from guide_items i where i.guide_id = (select id from guides where slug = $pb$aspiradores-escoba-sin-cable-menos-200$pb$) and i.position = 3), 'amazon', $pb$B0GPWHRFX6$pb$, $pb$https://www.amazon.es/dp/B0GPWHRFX6$pb$, 0);
