values ((select id from guides where slug = $pb$aspiradores-escoba-sin-cable-menos-200$pb$), 4, $pb$Dreame H12 Pro FlexReach$pb$, $pb$Para suelo duro$pb$, $pb$No es una escoba clásica sino un aspirador-fregona en seco y húmedo, para quien quiere dejar el cubo y la fregona. Friega con agua limpia en cada pasada, se tumba hasta 180° para entrar en huecos de 14 cm y, al terminar, se lava el rodillo a 90 °C y lo seca con aire caliente. Indica 18.000 Pa de succión y limpieza de borde a borde en ambos lados. Su terreno es el suelo duro; para sofás o coche necesitarás otro aparato.$pb$, array[$pb$Autolimpieza del rodillo con agua caliente y secado$pb$, $pb$Se tumba del todo para fregar bajo los muebles$pb$, $pb$Limpia pegado al rodapié por ambos lados$pb$]::text[], array[$pb$Pensado para suelo duro, no para tapicerías$pb$, $pb$Depósito de 780 ml$pb$]::text[], $pb$[{"label":"Tipo","value":"Aspirador-fregona seco y húmedo"},{"label":"Succión","value":"18.000 Pa"},{"label":"Autonomía","value":"50 min"},{"label":"Autolimpieza","value":"Agua y secado a 90 °C"},{"label":"Ruido","value":"76 dB"}]$pb$::jsonb);
