values ((select id from guides where slug = $pb$aspiradores-escoba-sin-cable-menos-200$pb$), 5, $pb$VACTechPro 35 kPa$pb$, $pb$Si quieres gastar lo mínimo$pb$, $pb$El más barato de la lista y una buena opción para un piso pequeño o como segundo aspirador para el coche y los sofás. Se convierte en aspirador de mano con boquilla para rendijas y combinada, tiene luz verde en el cepillo, filtro HEPA y batería extraíble. La autonomía es corta: hasta 35 minutos en modo ECO y 18 en máximo. A cambio, es el más silencioso según las fichas.$pb$, array[$pb$El más económico de la guía$pb$, $pb$Batería extraíble$pb$, $pb$52 dB declarados, el más silencioso$pb$]::text[], array[$pb$Solo 18 minutos en potencia máxima$pb$, $pb$Solo dos niveles de potencia$pb$]::text[], $pb$[{"label":"Succión","value":"35 kPa"},{"label":"Autonomía","value":"35 min ECO / 18 min MAX"},{"label":"Depósito","value":"1,5 L"},{"label":"Filtro","value":"HEPA"},{"label":"Ruido","value":"52 dB"}]$pb$::jsonb);
