insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$taladros-atornilladores-bateria$pb$), 1, $pb$Bosch UniversalImpact 18V$pb$, $pb$Mejor en general$pb$, $pb$El que recomendaríamos para una casa donde se hace un poco de todo. Es un 3 en 1: atornilla, taladra y taladra con percusión en mampostería, así que vale para colgar estanterías. Tiene 20 ajustes de par, dos velocidades, portabrocas de 13 mm de cierre rápido y viene en maletín con puntas y brocas para madera y pared. Su batería forma parte de la alianza Power for All. La pega es que el pack solo trae una batería de 2,0 Ah.$pb$, array[$pb$Función de percusión para ladrillo y mampostería$pb$, $pb$Portabrocas de 13 mm de liberación rápida$pb$, $pb$Maletín con 32 piezas para atornillar y 10 brocas$pb$]::text[], array[$pb$Solo incluye una batería$pb$, $pb$Más pesado que los modelos de 12 V$pb$]::text[], $pb$[{"label":"Voltaje","value":"18 V"},{"label":"Par máximo","value":"34 Nm"},{"label":"Velocidad máxima","value":"1350 rpm"},{"label":"Portabrocas","value":"13 mm"},{"label":"Batería incluida","value":"1 × 2,0 Ah"}]$pb$::jsonb);
insert into guide_item_stores (guide_item_id, store, external_id, url, position)
values ((select i.id from guide_items i where i.guide_id = (select id from guides where slug = $pb$taladros-atornilladores-bateria$pb$) and i.position = 1), 'amazon', $pb$B09877WFM6$pb$, $pb$https://www.amazon.es/dp/B09877WFM6$pb$, 0);
insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$taladros-atornilladores-bateria$pb$), 2, $pb$Einhell TE-CD 18/40 con 2 baterías$pb$, $pb$Mejor relación calidad-precio$pb$, $pb$Un percutor de 18 V muy completo para lo que cuesta: trae dos baterías de 2,0 Ah, cargador, maletín y un juego de 64 accesorios. Según su ficha da 40 Nm de par con 21 niveles, caja de dos velocidades, portabrocas de 13 mm de un solo casquillo y luz LED. Pertenece a la familia Power X-Change, que comparte baterías con las herramientas de jardín de Einhell. Encaja si ya tienes jardín Einhell.$pb$, array[$pb$Dos baterías de 2,0 Ah en la caja$pb$, $pb$40 Nm de par, el más alto de la guía$pb$, $pb$Baterías compatibles con el jardín Einhell$pb$]::text[], array[$pb$Baterías no intercambiables con Bosch u otras marcas$pb$, $pb$Peso y tamaño propios de un 18 V$pb$]::text[], $pb$[{"label":"Voltaje","value":"18 V"},{"label":"Par","value":"40 Nm"},{"label":"Niveles de par","value":"21"},{"label":"Portabrocas","value":"13 mm"},{"label":"Baterías incluidas","value":"2 × 2,0 Ah"}]$pb$::jsonb);
