insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$taladros-atornilladores-bateria$pb$), 3, $pb$Bosch Professional GSB 12V-15$pb$, $pb$Para uso frecuente$pb$, $pb$La gama azul de Bosch, pensada para un uso más intensivo pero en formato compacto de 12 V. Tiene percusión para mampostería, engranaje planetario de dos velocidades, portabrocas Autolock de 10 mm y llega a brocas de 19 mm en madera. El pack incluye dos baterías de 2,0 Ah, cargador, juegos de brocas para madera y metal y puntas. Encaja si haces reformas a menudo y quieres una herramienta manejable para trabajar por encima de la cabeza.$pb$, array[$pb$Dos baterías y sets de brocas en el pack$pb$, $pb$Compacto y ligero para su capacidad$pb$, $pb$Compatible con todo el sistema Professional 12 V$pb$]::text[], array[$pb$Portabrocas de 10 mm, admite brocas menos gruesas$pb$, $pb$Baterías no compatibles con la gama verde de Bosch$pb$]::text[], $pb$[{"label":"Voltaje","value":"12 V"},{"label":"Par máximo","value":"30 Nm"},{"label":"Broca máx. en madera","value":"19 mm"},{"label":"Portabrocas","value":"10 mm Autolock"},{"label":"Baterías incluidas","value":"2 × 2,0 Ah"}]$pb$::jsonb);
