insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$taladros-atornilladores-bateria$pb$), 4, $pb$Bosch EasyDrill 1200$pb$, $pb$Para pequeños arreglos en casa$pb$, $pb$Un taladro atornillador de 12 V para quien monta muebles, cambia herrajes y hace algún agujero en madera, metal o plástico. Tiene 20 niveles de par, luz LED para ver en rincones oscuros y una batería de 2,0 Ah compatible con toda la gama verde Bosch de 12 V. Viene con brocas y puntas en una funda blanda. No tiene percusión, así que no es la herramienta para colgar cosas en una pared de ladrillo.$pb$, array[$pb$Luz LED para rincones oscuros$pb$, $pb$20 niveles de par para no pasar de rosca$pb$, $pb$Batería compatible con la gama verde Bosch 12 V$pb$]::text[], array[$pb$Sin percusión: no sirve para mampostería$pb$, $pb$Una sola batería$pb$]::text[], $pb$[{"label":"Voltaje","value":"12 V"},{"label":"Par máximo","value":"30 Nm"},{"label":"Niveles de par","value":"20"},{"label":"Batería incluida","value":"1 × 2,0 Ah"},{"label":"Materiales","value":"Madera, metal y plástico"}]$pb$::jsonb);
