insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$taladros-atornilladores-bateria$pb$), 5, $pb$Bosch IXO 7 con adaptador en ángulo$pb$, $pb$La más compacta$pb$, $pb$No es un taladro, es un atornillador de bolsillo, y precisamente por eso es el que más vas a usar para montar muebles o apretar tornillos de enchufes y bisagras. La séptima generación da 5,5 Nm, atornilla hasta 190 tornillos por carga según Bosch y trae un adaptador en ángulo para rincones, 10 puntas y cable micro USB para cargar. Es la opción para gastar lo mínimo si no necesitas perforar.$pb$, array[$pb$Cabe en un cajón: 12 × 4,6 × 14,7 cm$pb$, $pb$Adaptador en ángulo para esquinas$pb$, $pb$Piezas de recambio durante 10 años$pb$]::text[], array[$pb$Solo atornilla, no taladra$pb$, $pb$Carga por micro USB, no USB-C$pb$]::text[], $pb$[{"label":"Voltaje","value":"3,6 V"},{"label":"Par","value":"5,5 Nm"},{"label":"Batería","value":"Litio 2,0 Ah"},{"label":"Tornillos por carga","value":"Hasta 190"},{"label":"Velocidad","value":"235 rpm"}]$pb$::jsonb);
