values ((select i.id from guide_items i where i.guide_id = (select id from guides where slug = $pb$cortacespedes-y-robots-cortacesped$pb$) and i.position = 1), 'amazon', $pb$B0DN5YD69K$pb$, $pb$https://www.amazon.es/dp/B0DN5YD69K$pb$, 0);
insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$cortacespedes-y-robots-cortacesped$pb$), 2, $pb$Einhell RASARRO 36/38 con 2 baterías$pb$, $pb$Para jardines medianos sin cables$pb$, $pb$Si quieres olvidarte del cable en un jardín de buen tamaño, este Einhell se recomienda para hasta 450 m². Funciona con dos baterías Power X-Change de 4,0 Ah, que vienen incluidas junto a un cargador doble. El motor es sin escobillas, corta 38 cm y la altura se ajusta en 6 niveles, de 25 a 75 mm. Lleva ruedas grandes tipo highwheeler para empujarlo mejor, aunque con 17,3 kg es el más pesado de la lista.$pb$, array[$pb$Baterías y cargador doble incluidos$pb$, $pb$6 alturas de corte, de 25 a 75 mm$pb$, $pb$Baterías compatibles con todo Einhell Power X-Change$pb$]::text[], array[$pb$17,3 kg, el más pesado de la guía$pb$, $pb$Piezas de recambio garantizadas solo 2 años según la ficha$pb$]::text[], $pb$[{"label":"Alimentación","value":"2 baterías Power X-Change de 4,0 Ah"},{"label":"Ancho de corte","value":"38 cm"},{"label":"Altura de corte","value":"25-75 mm, 6 niveles"},{"label":"Superficie recomendada","value":"Hasta 450 m²"},{"label":"Peso","value":"17,3 kg"}]$pb$::jsonb);
