values ((select i.id from guide_items i where i.guide_id = (select id from guides where slug = $pb$cortacespedes-y-robots-cortacesped$pb$) and i.position = 2), 'amazon', $pb$B07L1KM4Q2$pb$, $pb$https://www.amazon.es/dp/B07L1KM4Q2$pb$, 0);
insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$cortacespedes-y-robots-cortacesped$pb$), 3, $pb$Segway Navimow i105E$pb$, $pb$Para no volver a segar$pb$, $pb$El robot de la guía, para jardines de hasta 600 m² según Segway. No necesita cable perimetral: marcas los límites con el móvil y se orienta combinando RTK y una cámara de 140° que, según la ficha, reconoce más de 20 tipos de obstáculos. Desde la app gestionas varias zonas, horarios y dirección de corte. A cambio, corta solo 18 cm de ancho por pasada y es, con diferencia, la compra más cara de la lista.$pb$, array[$pb$Sin cable perimetral que enterrar$pb$, $pb$App con varias zonas y horarios$pb$, $pb$Detección de obstáculos por cámara$pb$]::text[], array[$pb$Muy por encima del resto en precio$pb$, $pb$Necesita instalar la antena y cobertura en todo el jardín$pb$]::text[], $pb$[{"label":"Tipo","value":"Robot cortacésped"},{"label":"Superficie máxima","value":"600 m²"},{"label":"Ancho de corte","value":"18 cm"},{"label":"Navegación","value":"RTK y cámara de 140°"},{"label":"Peso","value":"10,9 kg"}]$pb$::jsonb);
insert into guide_item_stores (guide_item_id, store, external_id, url, position)
values ((select i.id from guide_items i where i.guide_id = (select id from guides where slug = $pb$cortacespedes-y-robots-cortacesped$pb$) and i.position = 3), 'amazon', $pb$B0CXDNFZLL$pb$, $pb$https://www.amazon.es/dp/B0CXDNFZLL$pb$, 0);
insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$cortacespedes-y-robots-cortacesped$pb$), 4, $pb$Einhell GC-EM 1232$pb$, $pb$Si quieres gastar lo mínimo$pb$, $pb$El más barato de la lista y suficiente para césped de hasta 300 m² si tienes enchufe a mano. Corta 32 cm de ancho, regula la altura en 3 niveles con una sola rueda y recoge en un cajón de 30 litros. La guía se pliega para guardarlo, pesa 9,2 kg y la carcasa es de plástico resistente a golpes. Requiere un pequeño montaje al sacarlo de la caja y tiene menos ajustes de altura que los modelos más completos.$pb$, array[$pb$El más económico de la guía$pb$, $pb$Ligero, 9,2 kg$pb$, $pb$Guía plegable para guardarlo$pb$]::text[], array[$pb$Solo 3 alturas de corte$pb$, $pb$Cable y montaje inicial$pb$]::text[], $pb$[{"label":"Alimentación","value":"Cable"},{"label":"Ancho de corte","value":"32 cm"},{"label":"Cajón de recogida","value":"30 L"},{"label":"Superficie recomendada","value":"Hasta 300 m²"},{"label":"Peso","value":"9,2 kg"}]$pb$::jsonb);
