values ((select i.id from guide_items i where i.guide_id = (select id from guides where slug = $pb$cortacespedes-y-robots-cortacesped$pb$) and i.position = 4), 'amazon', $pb$B0853SGPMB$pb$, $pb$https://www.amazon.es/dp/B0853SGPMB$pb$, 0);
insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$cortacespedes-y-robots-cortacesped$pb$), 5, $pb$Einhell GE-CM 18/30 Li (sin batería)$pb$, $pb$Para patios pequeños$pb$, $pb$Pensado para céspedes urbanos de hasta 150 m², es el más ligero de la guía con 8,87 kg y tiene asa de transporte integrada, útil si lo guardas en un trastero o hay escalones. Corta 30 cm y ajusta la altura en 3 etapas. Ojo: es la versión Solo, sin batería ni cargador. Tiene sentido si ya tienes baterías Einhell compatibles de otras herramientas (confírmalo en la ficha del fabricante); si no, súmalas al presupuesto.$pb$, array[$pb$El más ligero, 8,87 kg$pb$, $pb$Asa de transporte integrada$pb$, $pb$Aprovecha baterías Einhell compatibles que ya tengas$pb$]::text[], array[$pb$Se vende sin batería ni cargador$pb$, $pb$Solo para superficies pequeñas, hasta 150 m²$pb$]::text[], $pb$[{"label":"Batería","value":"No incluida (versión Solo)"},{"label":"Ancho de corte","value":"30 cm"},{"label":"Altura de corte","value":"3 niveles"},{"label":"Superficie recomendada","value":"Hasta 150 m²"},{"label":"Peso","value":"8,87 kg"}]$pb$::jsonb);
