values ((select id from guides where slug = $pb$tablets-menos-200$pb$), 1, $pb$Xiaomi Redmi Pad 2 9,7" 4+64 GB$pb$, $pb$Mejor en general$pb$, $pb$La más equilibrada para casi todo. Su pantalla 2K de 9,7 pulgadas a 120 Hz es muy fluida, el Snapdragon 6s Gen 2 va sobrado para el uso diario y la batería de 7600 mAh con carga de 18 W promete hasta 1,7 días. El cuerpo es de aluminio y Xiaomi da 4 años de garantía sin activar nada. Las pegas: solo 64 GB y, según la ficha, en la caja vienen el cable y el extractor de SIM, no el cargador.$pb$, array[$pb$Pantalla 2K a 120 Hz$pb$, $pb$4 años de garantía del fabricante$pb$, $pb$Cuerpo unibody de aluminio$pb$]::text[], array[$pb$64 GB de almacenamiento$pb$, $pb$Sin cargador en la caja según la ficha$pb$]::text[], $pb$[{"label":"Pantalla","value":"9,7\" 2K, 120 Hz"},{"label":"Procesador","value":"Snapdragon 6s Gen 2"},{"label":"Memoria","value":"4 GB + 64 GB"},{"label":"Batería","value":"7600 mAh, carga 18 W"},{"label":"Garantía","value":"4 años"}]$pb$::jsonb);
