values ((select id from guides where slug = $pb$tablets-menos-200$pb$), 2, $pb$TCL NXTPAPER 11 Plus 8+256 GB$pb$, $pb$Para leer y estudiar$pb$, $pb$La opción para quien lee mucho o estudia con PDF. Su pantalla NXTPAPER 4.0 de 11,45 pulgadas y 2.2K imita el papel para cansar menos la vista. Es también la que más memoria trae: 8 GB de RAM y 256 GB de almacenamiento, con un Helio G100, cuatro altavoces, cámaras de 8 MP delante y detrás y Android 15. Incluye cargador de 33 W. La pega: está cerca del tope de la guía y la ficha no indica la capacidad de la batería.$pb$, array[$pb$8 GB de RAM y 256 GB de almacenamiento$pb$, $pb$Pantalla tipo papel para leer más rato$pb$, $pb$Cargador de 33 W en la caja$pb$]::text[], array[$pb$Cerca del tope de precio de la guía$pb$, $pb$La ficha no indica la batería$pb$]::text[], $pb$[{"label":"Pantalla","value":"11,45\" 2.2K NXTPAPER 4.0"},{"label":"Procesador","value":"MediaTek Helio G100"},{"label":"Memoria","value":"8 GB + 256 GB"},{"label":"Cámaras","value":"8 MP frontal y trasera"},{"label":"Sistema","value":"Android 15"}]$pb$::jsonb);
