values ((select id from guides where slug = $pb$tablets-menos-200$pb$), 3, $pb$HONOR Pad X8a 11" 4+64 GB$pb$, $pb$Mejor relación calidad-precio$pb$, $pb$Mucha pantalla y mucha batería por poco dinero. Tiene 11 pulgadas a 90 Hz con resolución 1920 x 1200 y certificaciones de luz azul reducida, y una batería de 8300 mAh que HONOR cifra en hasta 14 horas de vídeo. Pesa 495 g con 7,25 mm de grosor, cuerpo metálico y cuatro altavoces. MagicOS 8 permite dividir la pantalla hasta en 4 apps. La pega: el Snapdragon 680 va justo en juegos y 64 GB se quedan cortos si no amplías el almacenamiento.$pb$, array[$pb$Hasta 14 horas de vídeo según HONOR$pb$, $pb$11 pulgadas a 90 Hz$pb$, $pb$Almacenamiento ampliable hasta 1 TB$pb$]::text[], array[$pb$Snapdragon 680, más justo en juegos$pb$, $pb$64 GB de almacenamiento$pb$]::text[], $pb$[{"label":"Pantalla","value":"11\" 1920 x 1200, 90 Hz"},{"label":"Procesador","value":"Snapdragon 680"},{"label":"Memoria","value":"4 GB + 64 GB"},{"label":"Batería","value":"8300 mAh"},{"label":"Peso y grosor","value":"495 g, 7,25 mm"}]$pb$::jsonb);
