values ((select id from guides where slug = $pb$tablets-menos-200$pb$), 4, $pb$Lenovo Tab 10,1" con funda$pb$, $pb$Para familias$pb$, $pb$Una buena tablet para compartir en casa o dejar a los niños, porque viene con funda transparente y cargador de 20 W. La pantalla WUXGA de 10,1 pulgadas va bien para dibujos y series, los dos altavoces tienen Dolby Atmos y el Helio G85 basta para apps y juegos sencillos. Lenovo indica hasta 9,5 horas de YouTube con su batería de 5100 mAh. La pega: su pantalla va a 60 Hz y la batería, de 5100 mAh, es más pequeña que la de la Redmi o la HONOR.$pb$, array[$pb$Funda transparente y cargador incluidos$pb$, $pb$Altavoces con Dolby Atmos$pb$, $pb$Ranura microSD$pb$]::text[], array[$pb$Batería de 5100 mAh$pb$, $pb$Pantalla a 60 Hz$pb$]::text[], $pb$[{"label":"Pantalla","value":"10,1\" WUXGA, 60 Hz"},{"label":"Procesador","value":"MediaTek Helio G85"},{"label":"Memoria","value":"4 GB + 64 GB"},{"label":"Batería","value":"5100 mAh, hasta 9,5 h de vídeo"},{"label":"Conectividad","value":"Wi-Fi 5, Bluetooth 5.3"}]$pb$::jsonb);
