values ((select id from guides where slug = $pb$moviles-menos-300$pb$), 1, $pb$Redmi Note 17 6+256 GB$pb$, $pb$Mejor en general$pb$, $pb$El más completo para un uso normal. Tiene una batería de 7700 mAh con carga de 45 W y carga inversa por cable, pantalla GOLED FHD+ de 6,99 pulgadas con Gorilla Glass 7i, certificación IP65 y cámara principal de 50 MP con frontal de 16 MP. Trae 256 GB y 4 años de garantía de Xiaomi sin activar nada. La pega: la ficha no indica si es 5G y el altavoz es mono.$pb$, array[$pb$Batería de 7700 mAh$pb$, $pb$256 GB y 4 años de garantía$pb$, $pb$Resistencia al agua y al polvo IP65$pb$]::text[], array[$pb$La ficha no indica 5G$pb$, $pb$Altavoz mono$pb$]::text[], $pb$[{"label":"Red","value":"La ficha no lo indica"},{"label":"Pantalla","value":"6,99\" GOLED FHD+"},{"label":"Memoria","value":"6 GB + 256 GB"},{"label":"Batería","value":"7700 mAh, carga 45 W"},{"label":"Cámaras","value":"50 MP + 16 MP frontal"},{"label":"Resistencia","value":"IP65"}]$pb$::jsonb);
