values ((select id from guides where slug = $pb$moviles-menos-300$pb$), 2, $pb$realme 14T 5G 8+256 GB$pb$, $pb$La más resistente$pb$, $pb$Para quien tiene el móvil siempre en la mano en la obra, en la playa o con niños cerca. Su certificación IP69 aguanta chorros de agua a presión e inmersión. Además es 5G con un Dimensity 6300, trae 8 GB de RAM y 256 GB, pantalla AMOLED de 6,67 pulgadas a 120 Hz, batería de 5130 mAh con carga de 45 W y jack de auriculares. Según la ficha es de una sola SIM, algo a tener en cuenta si usas dos líneas.$pb$, array[$pb$Certificación IP69$pb$, $pb$5G con 8 GB de RAM y 256 GB$pb$, $pb$Pantalla AMOLED a 120 Hz y jack de 3,5 mm$pb$]::text[], array[$pb$Una sola SIM según la ficha$pb$, $pb$Batería menor que la del Redmi Note 17$pb$]::text[], $pb$[{"label":"Red","value":"5G"},{"label":"Pantalla","value":"6,67\" AMOLED, 120 Hz"},{"label":"Procesador","value":"MediaTek Dimensity 6300"},{"label":"Memoria","value":"8 GB + 256 GB"},{"label":"Batería","value":"5130 mAh, carga 45 W"},{"label":"Resistencia","value":"IP69"}]$pb$::jsonb);
