values ((select id from guides where slug = $pb$moviles-menos-300$pb$), 3, $pb$Motorola Moto G56 5G 8/256 GB$pb$, $pb$Para series y vídeos$pb$, $pb$Si ves mucho contenido en el móvil, el Moto G56 suma pantalla FHD+ de 6,72 pulgadas a 120 Hz y altavoces estéreo. Es 5G, con 8 GB de RAM, 256 GB, doble SIM, cámara de 50 MP con gran angular y batería de 5200 mAh con carga TurboPower. La trasera es de material vegano y el frontal, Gorilla Glass 7i. La pega: es el más caro de la guía y la ficha no indica certificación IP.$pb$, array[$pb$Altavoces estéreo$pb$, $pb$5G, 8 GB de RAM y 256 GB$pb$, $pb$Cámara con gran angular$pb$]::text[], array[$pb$El más caro de la lista$pb$, $pb$Sin certificación IP indicada en la ficha$pb$]::text[], $pb$[{"label":"Red","value":"5G"},{"label":"Pantalla","value":"6,72\" FHD+, 120 Hz"},{"label":"Memoria","value":"8 GB + 256 GB"},{"label":"Batería","value":"5200 mAh, TurboPower"},{"label":"Cámara","value":"50 MP + gran angular"},{"label":"SIM","value":"Dual SIM"}]$pb$::jsonb);
