insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$moviles-menos-300$pb$), 4, $pb$Samsung Galaxy A17 5G 4+128 GB$pb$, $pb$Si prefieres Samsung$pb$, $pb$Para quien quiere quedarse en Samsung por costumbre o por el resto de dispositivos de casa. Es 5G, con procesador Exynos 1330, 4 GB de RAM y 128 GB, doble SIM, lector de huellas y USB-C. La ficha de Amazon es muy escueta y no detalla pantalla ni batería, y además indica que no es resistente al agua. Con 4 GB de RAM va bien para lo habitual, pero se queda por detrás de los otros 5G de la guía en memoria.$pb$, array[$pb$5G y doble SIM$pb$, $pb$128 GB de almacenamiento$pb$, $pb$Lector de huellas$pb$]::text[], array[$pb$No resistente al agua según la ficha$pb$, $pb$4 GB de RAM y ficha con pocos datos$pb$]::text[], $pb$[{"label":"Red","value":"5G"},{"label":"Procesador","value":"Exynos 1330"},{"label":"Memoria","value":"4 GB + 128 GB"},{"label":"SIM","value":"Dual SIM nano"},{"label":"Desbloqueo","value":"Huella dactilar"}]$pb$::jsonb);
