values ((select id from guides where slug = $pb$moviles-menos-300$pb$), 5, $pb$Xiaomi Redmi A5 3+64 GB$pb$, $pb$Si quieres gastar lo mínimo$pb$, $pb$Un móvil básico para llamadas, WhatsApp y poco más, o como teléfono de repuesto o para una persona mayor. Tiene una pantalla grande de 6,88 pulgadas a 120 Hz, batería de 5200 mAh, cámara dual de 32 MP, doble SIM y lector de huellas. La ficha no menciona 5G. Los límites son claros: 3 GB de RAM, 64 GB de almacenamiento y cargador no incluido.$pb$, array[$pb$Doble SIM y lector de huellas$pb$, $pb$Pantalla de 6,88" a 120 Hz$pb$, $pb$Batería de 5200 mAh$pb$]::text[], array[$pb$3 GB de RAM y 64 GB, justo para apps pesadas$pb$, $pb$Cargador no incluido$pb$]::text[], $pb$[{"label":"Red","value":"La ficha no lo indica"},{"label":"Pantalla","value":"6,88\", 120 Hz"},{"label":"Memoria","value":"3 GB + 64 GB"},{"label":"Batería","value":"5200 mAh"},{"label":"Cámara","value":"Dual de 32 MP"}]$pb$::jsonb);
