values ((select id from guides where slug = $pb$zapatillas-running-empezar-a-correr$pb$), 1, $pb$ASICS Gel-Contend 9$pb$, $pb$Mejor en general$pb$, $pb$Una zapatilla sencilla y bien equipada para empezar a correr. Lleva amortiguación GEL en la parte trasera del pie para suavizar el impacto, parte superior de malla jacquard que ventila, plantilla OrthoLite y ranuras flexibles en la suela. Las costuras sintéticas en los refuerzos ayudan a sujetar el pie. La pega está en la talla: la propia ficha avisa de que talla pequeño y aconseja pedir media talla o una más.$pb$, array[$pb$Amortiguación GEL en el talón$pb$, $pb$Plantilla OrthoLite$pb$, $pb$Suela con ranuras flexibles$pb$]::text[], array[$pb$Talla pequeña según la propia ficha$pb$, $pb$Ficha en versión de hombre$pb$]::text[], $pb$[{"label":"Amortiguación","value":"GEL en la parte trasera"},{"label":"Parte superior","value":"Malla jacquard"},{"label":"Plantilla","value":"OrthoLite"},{"label":"Suela","value":"Caucho"},{"label":"Talla","value":"Pide media talla o una más"}]$pb$::jsonb);
