values ((select id from guides where slug = $pb$zapatillas-running-empezar-a-correr$pb$), 2, $pb$New Balance 520v3$pb$, $pb$Para rodar a diario$pb$, $pb$Pensada, según su ficha, para la carrera diaria y con soporte neutro, encaja con quien ya ha cogido el hábito y sale varias veces por semana. Su entresuela Fresh Foam busca una amortiguación suave y ligera, y la parte superior es de mesh técnico transpirable. Figura como acolchada, flexible, ligera y lavable. Para pies que necesitan corrección de la pisada no es la opción, porque es neutra.$pb$, array[$pb$Entresuela Fresh Foam$pb$, $pb$Mesh técnico transpirable$pb$, $pb$Diseñada para la carrera diaria$pb$]::text[], array[$pb$Solo pisada neutra$pb$, $pb$Ficha en versión de hombre$pb$]::text[], $pb$[{"label":"Amortiguación","value":"Fresh Foam"},{"label":"Parte superior","value":"Mesh técnico transpirable"},{"label":"Pisada","value":"Neutra"},{"label":"Cierre","value":"Cordones"},{"label":"Cuidado","value":"Lavable"}]$pb$::jsonb);
