values ((select i.id from guide_items i where i.guide_id = (select id from guides where slug = $pb$zapatillas-running-empezar-a-correr$pb$) and i.position = 2), 'amazon', $pb$B0D1LDXSBL$pb$, $pb$https://www.amazon.es/dp/B0D1LDXSBL$pb$, 0);
