values ((select id from guides where slug = $pb$zapatillas-running-empezar-a-correr$pb$), 3, $pb$adidas Runfalcon 5$pb$, $pb$Para correr y para el día a día$pb$, $pb$Si buscas una zapatilla que valga para tus primeras salidas y también para llevar a diario, la Runfalcon 5 tiene mediasuela Cloudfoam, plantilla OrthoLite, empeine de malla y forro textil. La horma es clásica y figura como lavable. Su planteamiento es más de uso mixto que de entrenamiento serio, así que si vas a subir mucho el kilometraje compensa mirar un modelo más específico.$pb$, array[$pb$Mediasuela Cloudfoam y plantilla OrthoLite$pb$, $pb$Horma clásica$pb$, $pb$Lavable$pb$]::text[], array[$pb$Más de uso mixto que de entrenamiento intenso$pb$, $pb$Ficha en versión de hombre$pb$]::text[], $pb$[{"label":"Amortiguación","value":"Cloudfoam"},{"label":"Plantilla","value":"OrthoLite"},{"label":"Parte superior","value":"Malla con forro textil"},{"label":"Suela","value":"Caucho"},{"label":"Horma","value":"Clásica"}]$pb$::jsonb);
