values ((select id from guides where slug = $pb$zapatillas-running-empezar-a-correr$pb$), 4, $pb$adidas Duramo SL$pb$, $pb$Para quien busca ligereza$pb$, $pb$Una zapatilla ligera, con amortiguación LIGHTMOTION y forro textil, para quien quiere sentir el pie más suelto en carreras cortas o en la cinta del gimnasio. Su ficha indica que se puede lavar a máquina, algo práctico si corres con lluvia. Como en las ASICS, la ficha recomienda comprar una talla más grande, así que tenlo en cuenta antes de pedir tu número habitual.$pb$, array[$pb$Ligera, con amortiguación LIGHTMOTION$pb$, $pb$Se puede lavar a máquina$pb$, $pb$Suela de caucho$pb$]::text[], array[$pb$La ficha recomienda una talla más$pb$, $pb$Menos datos técnicos que otras de la guía$pb$]::text[], $pb$[{"label":"Amortiguación","value":"LIGHTMOTION"},{"label":"Forro","value":"Textil"},{"label":"Suela","value":"Caucho"},{"label":"Cuidado","value":"Lavable a máquina"},{"label":"Talla","value":"Pide una talla más"}]$pb$::jsonb);
