values ((select id from guides where slug = $pb$zapatillas-running-empezar-a-correr$pb$), 5, $pb$Nike Revolution 8$pb$, $pb$Para empezar sin complicarte$pb$, $pb$La entrada a las zapatillas de correr de Nike, sencilla y cómoda para tus primeras semanas. Lleva entresuela de espuma para una amortiguación sensible, parte superior de malla transpirable y suela de goma pensada para distintas superficies. En su ficha aparece como acolchada, flexible, ligera, antideslizante y lavable. No tiene tecnologías de amortiguación específicas como las otras marcas, así que encaja mejor con salidas cortas que con tiradas largas.$pb$, array[$pb$Malla transpirable$pb$, $pb$Suela de goma para varias superficies$pb$, $pb$Flexible y lavable$pb$]::text[], array[$pb$Amortiguación más básica$pb$, $pb$Mejor para salidas cortas que para tiradas largas$pb$]::text[], $pb$[{"label":"Amortiguación","value":"Entresuela de espuma"},{"label":"Parte superior","value":"Malla transpirable"},{"label":"Suela","value":"Goma"},{"label":"Cierre","value":"Cordones"},{"label":"Cuidado","value":"Lavable"}]$pb$::jsonb);
