insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$equipo-senderismo-para-empezar$pb$), 2, $pb$Salomon X Ultra Pioneer Gore-Tex (mujer)$pb$, $pb$La zapatilla para rutas de mujer$pb$, $pb$Para quien prefiere ir ligera y no quiere sentir el peso de una bota, esta zapatilla de senderismo de Salomon para mujer es la pieza que encaja. Lleva membrana Gore-Tex, así que es una buena compañera para caminos con barro o rocío por la mañana. Ten en cuenta que, al no tener caña, sujeta menos el tobillo en terreno muy suelto, y que la ficha de Amazon apenas detalla sus características técnicas.$pb$, array[$pb$Formato zapatilla, más cómoda en caminos$pb$, $pb$Membrana Gore-Tex$pb$, $pb$Modelo específico de mujer$pb$]::text[], array[$pb$Sin caña: sujeta menos el tobillo$pb$, $pb$Ficha de Amazon con muy pocos datos$pb$]::text[], $pb$[{"label":"Tipo","value":"Zapatilla de senderismo"},{"label":"Membrana","value":"Gore-Tex"},{"label":"Modelo","value":"X Ultra Pioneer"},{"label":"Público","value":"Mujer"}]$pb$::jsonb);
