values ((select id from guides where slug = $pb$equipo-senderismo-para-empezar$pb$), 3, $pb$Salomon Trailblazer 30$pb$, $pb$Mochila de día para monte y ciudad$pb$, $pb$La Trailblazer 30 es la mochila que puedes usar el sábado en la sierra y el lunes para ir a trabajar. Tiene 30 litros, un bolsillo en la espalda para lo que no quieres perder y bolsillos laterales elásticos para la botella. La espalda va acolchada, lleva cinturón y correas de compresión para que la carga no baile. Es ligera y sencilla: un solo compartimento principal y tres bolsillos. Si te gusta tener todo muy organizado o vas a usar bolsa de hidratación, la Skysper ofrece más divisiones.$pb$, array[$pb$Espalda acolchada y cinturón$pb$, $pb$Correas de compresión para fijar la carga$pb$, $pb$Sirve tanto para rutas como para el día a día$pb$]::text[], array[$pb$Un solo compartimento principal$pb$, $pb$La ficha no menciona compatibilidad con hidratación$pb$]::text[], $pb$[{"label":"Capacidad","value":"30 L"},{"label":"Bolsillos","value":"3"},{"label":"Resistencia al agua","value":"Resistente al agua"},{"label":"Cierre","value":"Cremallera"},{"label":"Arnés","value":"Espalda acolchada, cinturón y compresión"}]$pb$::jsonb);
