values ((select i.id from guide_items i where i.guide_id = (select id from guides where slug = $pb$equipo-senderismo-para-empezar$pb$) and i.position = 3), 'amazon', $pb$B0C5M35GLP$pb$, $pb$https://www.amazon.es/dp/B0C5M35GLP$pb$, 0);
