values ((select id from guides where slug = $pb$equipo-senderismo-para-empezar$pb$), 4, $pb$Skysper 30 L$pb$, $pb$Si quieres gastar lo mínimo en mochila$pb$, $pb$La Skysper es la alternativa económica de la guía y no va escasa de detalles. Tiene 30 litros repartidos en varios compartimentos, compatible con sistema de hidratación, y está hecha en nailon ripstop 210D y poliéster 600D. La espalda lleva malla transpirable con ranuras de ventilación, y añade cinturón desmontable, correa de pecho, silbato y elementos reflectantes. El fabricante recomienda no pasar de 8 kg de carga, así que es para rutas de un día, no para travesías con mucho peso.$pb$, array[$pb$Compatible con bolsa de hidratación$pb$, $pb$Espalda de malla ventilada$pb$, $pb$Silbato, correa de pecho y reflectantes$pb$]::text[], array[$pb$Carga máxima recomendada de 8 kg$pb$, $pb$Marca menos conocida que Salomon$pb$]::text[], $pb$[{"label":"Capacidad","value":"30 L"},{"label":"Material","value":"Nailon ripstop 210D y poliéster 600D"},{"label":"Compartimentos","value":"4"},{"label":"Hidratación","value":"Compatible"},{"label":"Carga máx. recomendada","value":"8 kg"}]$pb$::jsonb);
