values ((select i.id from guide_items i where i.guide_id = (select id from guides where slug = $pb$equipo-senderismo-para-empezar$pb$) and i.position = 4), 'amazon', $pb$B0DNZ6FFN6$pb$, $pb$https://www.amazon.es/dp/B0DNZ6FFN6$pb$, 0);
