values ((select id from guides where slug = $pb$equipo-senderismo-para-empezar$pb$), 5, $pb$Trekology Trek-Z (pareja)$pb$, $pb$Bastones para cuidar las rodillas$pb$, $pb$Los bastones son la pieza que menos gente compra al principio y la que más se agradece en las bajadas. Los Trek-Z se venden por parejas, son de aluminio y se pliegan en tres tramos hasta 38 cm, así que caben dentro de la mochila o en la maleta. Se ajustan con un cierre de doble clic en un rango de 20 cm, y la empuñadura es de EVA. Hay dos tallas según tu estatura; elige bien, porque cada una tiene su propio rango de longitud.$pb$, array[$pb$Plegados ocupan 38 cm$pb$, $pb$Ajuste rápido con cierre de doble clic$pb$, $pb$Se venden en pareja$pb$]::text[], array[$pb$Hay que elegir bien la talla según estatura$pb$, $pb$Plegables: algo menos rígidos que uno de una pieza$pb$]::text[], $pb$[{"label":"Unidades","value":"2 bastones"},{"label":"Material","value":"Aluminio"},{"label":"Longitud","value":"100-120 cm (estatura 150-178 cm)"},{"label":"Plegado","value":"38 cm"},{"label":"Peso por bastón","value":"294 g (talla 100-120 cm)"}]$pb$::jsonb);
