values ((select id from guides where slug = $pb$barbacoas-y-planchas-electricas$pb$), 1, $pb$Cecotec PerfectRoast 3000 Inox$pb$, $pb$Mejor en general$pb$, $pb$Es la eléctrica más completa de la lista y la que mejor resuelve una comida para varios. Tiene 3000 W, una superficie de 30 x 50 cm mitad grill y mitad plancha, y dos zonas con termostato independiente y 6 niveles cada una, así que puedes hacer la carne a fuego fuerte y las verduras a fuego suave a la vez. La placa es extraíble y antiadherente, y lleva un protector contra el viento plegable de acero inoxidable. Es grande: necesitas sitio en la mesa o en la terraza.$pb$, array[$pb$Dos zonas con temperatura independiente$pb$, $pb$Superficie mixta de grill y plancha$pb$, $pb$Placa extraíble y protector contra el viento$pb$]::text[], array[$pb$Ocupa bastante en la mesa$pb$, $pb$Necesita un enchufe que aguante 3000 W$pb$]::text[], $pb$[{"label":"Potencia","value":"3000 W"},{"label":"Superficie","value":"30 x 50 cm"},{"label":"Zonas","value":"2, con termostato propio"},{"label":"Niveles de temperatura","value":"6 por zona"},{"label":"Placa","value":"Aluminio fundido antiadherente, extraíble"}]$pb$::jsonb);
