values ((select i.id from guide_items i where i.guide_id = (select id from guides where slug = $pb$barbacoas-y-planchas-electricas$pb$) and i.position = 1), 'amazon', $pb$B09ZB7NF31$pb$, $pb$https://www.amazon.es/dp/B09ZB7NF31$pb$, 0);
insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$barbacoas-y-planchas-electricas$pb$), 2, $pb$Severin barbacoa de sobremesa 2200 W$pb$, $pb$La opción para balcón$pb$, $pb$Si tienes un balcón y quieres algo parecido a una barbacoa sin brasas, esta Severin es la candidata natural. Su bandeja recogegotas lleva agua para que la grasa no se queme ni haga humo, y la carcasa SafeTouch evita que las zonas que tocas se calienten en exceso. La temperatura se regula con un dial con anillo LED, la rejilla es de acero inoxidable y las piezas se desmontan para limpiar. La ficha indica que es apta para interior y exterior. A cambio, tiene una sola zona de cocinado y la ficha no indica la superficie de la rejilla.$pb$, array[$pb$Bandeja con agua que reduce el humo$pb$, $pb$Carcasa que no se calienta al tacto$pb$, $pb$Apta para interior y exterior$pb$]::text[], array[$pb$Una sola zona de cocinado$pb$, $pb$La ficha no indica la superficie de la rejilla$pb$]::text[], $pb$[{"label":"Potencia","value":"2200 W"},{"label":"Rejilla","value":"Acero inoxidable"},{"label":"Control","value":"Dial con anillo LED"},{"label":"Uso","value":"Interior y exterior"},{"label":"Extras","value":"Protector contra el viento, bandeja con agua"}]$pb$::jsonb);
