values ((select id from guides where slug = $pb$barbacoas-y-planchas-electricas$pb$), 3, $pb$Weber Compact Kettle (carbón)$pb$, $pb$Para quien quiere sabor a brasa$pb$, $pb$La única de carbón de la guía y la que tienes que elegir si el sabor ahumado no es negociable. Tiene cuba y tapa de acero vitrificado, parrilla de acero cromado y una superficie de cocción de 44,5 cm de diámetro, que da para una comida en familia. El sistema One-Touch facilita retirar la ceniza al terminar, y el soporte de tres patas con ruedas permite moverla por la terraza o el jardín. Lo que pega: necesita espacio al aire libre y tiempo para encender el carbón, y llega para montar.$pb$, array[$pb$Cuba y tapa de acero vitrificado$pb$, $pb$Sistema One-Touch para retirar la ceniza$pb$, $pb$Tres patas con ruedas para moverla$pb$]::text[], array[$pb$Solo para exteriores con espacio$pb$, $pb$Requiere montaje$pb$]::text[], $pb$[{"label":"Combustible","value":"Carbón"},{"label":"Superficie de cocción","value":"44,5 cm de diámetro"},{"label":"Parrilla","value":"Acero cromado"},{"label":"Cuba y tapa","value":"Acero vitrificado"},{"label":"Limpieza de ceniza","value":"Sistema One-Touch"},{"label":"Soporte","value":"Tres patas con ruedas"}]$pb$::jsonb);
