values ((select id from guides where slug = $pb$barbacoas-y-planchas-electricas$pb$), 5, $pb$Jata GR558 2500 W$pb$, $pb$Si quieres gastar lo mínimo$pb$, $pb$La opción más barata de la lista y una plancha de las de siempre. Tiene 2500 W y una superficie de 46 x 28 cm, suficiente para dos o tres personas. Su sistema Super Diet inclina ligeramente la plancha para que la grasa y las salsas se vayan hacia un lado. Una vez apagada mantiene el calor y las asas no se calientan, así que puedes llevarla a la mesa. La marca destaca su revestimiento libre de PFOA. No tiene termostato regulable: la ficha indica un solo ajuste.$pb$, array[$pb$Inclinación para escurrir la grasa$pb$, $pb$Asas frías para llevarla a la mesa$pb$, $pb$Libre de PFOA según el fabricante$pb$]::text[], array[$pb$Sin regulación de temperatura$pb$, $pb$Superficie justa para más de tres personas$pb$]::text[], $pb$[{"label":"Potencia","value":"2500 W"},{"label":"Superficie","value":"46 x 28 cm"},{"label":"Ajustes","value":"1"},{"label":"Sistema","value":"Super Diet (plancha inclinada)"},{"label":"Tensión","value":"230 V"}]$pb$::jsonb);
