insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$ventiladores-silenciosos-verano$pb$), 1, $pb$Xiaomi Smart Ventilador de Pie 2 en 1$pb$, $pb$Mejor en general$pb$, $pb$Es el más versátil de la guía. Funciona como circulador, mueve 1440 m³/h con un alcance de 13 metros y oscila en 3D: 120° en horizontal y 100° en vertical. Se puede usar de pie o sobre una mesa, y su motor DC marca 27,9 dB a la velocidad más baja según el fabricante. Desde la app Xiaomi Home ajustas hasta 100 niveles de velocidad. Quien no quiera depender del móvil puede echar en falta un control más directo de todo desde el propio aparato.$pb$, array[$pb$Oscilación horizontal y vertical$pb$, $pb$De mesa o de pie$pb$, $pb$100 niveles de velocidad desde la app$pb$]::text[], array[$pb$Parte del control depende de la app$pb$, $pb$Consume 50 W, más que la torre Levoit$pb$]::text[], $pb$[{"label":"Caudal","value":"1440 m³/h"},{"label":"Alcance","value":"13 m"},{"label":"Oscilación","value":"120° horizontal, 100° vertical"},{"label":"Velocidades","value":"100 (app)"},{"label":"Potencia","value":"50 W"}]$pb$::jsonb);
