insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$ventiladores-silenciosos-verano$pb$), 2, $pb$DREO ventilador de pie con motor DC$pb$, $pb$La opción silenciosa para dormir$pb$, $pb$Pensado para el dormitorio. El fabricante habla de 20 dB a baja velocidad, aunque la ficha técnica indica 28,2 dB; en cualquier caso, es de los más tranquilos de la lista, y permite silenciar los pitidos de los botones. Tiene 8 velocidades, modo automático, oscilación de 90° y un cabezal que se inclina hasta 105°. La altura va de 96 a 106 cm, y la rejilla y el aspa se desmontan para limpiarlos. Trae mando a distancia. Su recorrido de altura es corto si lo quieres por encima de una cama alta.$pb$, array[$pb$Muy tranquilo a baja velocidad$pb$, $pb$Aspa y rejillas desmontables$pb$, $pb$Modo automático y mando a distancia$pb$]::text[], array[$pb$Poco margen de altura (96-106 cm)$pb$, $pb$Oscilación limitada a 90°$pb$]::text[], $pb$[{"label":"Motor","value":"DC"},{"label":"Velocidades","value":"8"},{"label":"Oscilación","value":"90°"},{"label":"Altura","value":"96-106 cm"},{"label":"Caudal","value":"1444 m³/h"}]$pb$::jsonb);
