insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$ventiladores-silenciosos-verano$pb$), 3, $pb$Cecotec EnergySilence 1030 SmartExtreme$pb$, $pb$Mejor relación calidad-precio$pb$, $pb$Un ventilador de pie clásico, con aspas de 40 cm, pero con motor DC de 28 W. Lo que más llama la atención son sus 24 velocidades y tres modos (Eco, Sleep y Turbo), que permiten afinar mucho el caudal. Trae mando a distancia, pantalla LED, temporizador de hasta 18 horas y una barra telescópica que va de 115 a 135 cm. La ficha no da una cifra de ruido, así que en ese punto toca fiarse de las opiniones de los compradores.$pb$, array[$pb$24 velocidades y modo Sleep$pb$, $pb$Temporizador de hasta 18 horas$pb$, $pb$Altura de 115 a 135 cm$pb$]::text[], array[$pb$La ficha no indica decibelios$pb$, $pb$Formato clásico, menos alcance que un circulador$pb$]::text[], $pb$[{"label":"Motor","value":"DC, 28 W"},{"label":"Diámetro","value":"40 cm, 10 aspas"},{"label":"Velocidades","value":"24"},{"label":"Temporizador","value":"Hasta 18 h"},{"label":"Altura","value":"115-135 cm"}]$pb$::jsonb);
