values ((select i.id from guide_items i where i.guide_id = (select id from guides where slug = $pb$ventiladores-silenciosos-verano$pb$) and i.position = 3), 'amazon', $pb$B092J7CGXT$pb$, $pb$https://www.amazon.es/dp/B092J7CGXT$pb$, 0);
insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$ventiladores-silenciosos-verano$pb$), 4, $pb$Rowenta Turbo Silence Extreme VU5640$pb$, $pb$Para salones grandes$pb$, $pb$Si buscas mover mucho aire en una estancia amplia, este Rowenta es el que más empuje tiene en la ficha: 70 W, cinco palas y hasta 72 m³ por minuto a máxima velocidad según el fabricante. Incluye el modo Silent Night para la noche y Turbo Boost para enfriar rápido, con oscilación automática de 120°. A velocidad mínima marca 45 dB, más que los demás modelos que indican ruido, así que encaja mejor en el salón que junto a la cama. Se maneja con botones en el propio aparato.$pb$, array[$pb$Mucho caudal para estancias amplias$pb$, $pb$Modos Silent Night y Turbo Boost$pb$, $pb$Oscilación de 120°$pb$]::text[], array[$pb$45 dB a velocidad mínima$pb$, $pb$La ficha no menciona mando a distancia$pb$]::text[], $pb$[{"label":"Potencia","value":"70 W"},{"label":"Palas","value":"5"},{"label":"Velocidades","value":"4"},{"label":"Ruido mínimo","value":"45 dB(A)"},{"label":"Oscilación","value":"120°"}]$pb$::jsonb);
