values ((select i.id from guide_items i where i.guide_id = (select id from guides where slug = $pb$ventiladores-silenciosos-verano$pb$) and i.position = 4), 'amazon', $pb$B01891LZBY$pb$, $pb$https://www.amazon.es/dp/B01891LZBY$pb$, 0);
insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$ventiladores-silenciosos-verano$pb$), 5, $pb$Levoit torre compacta LTF-F132$pb$, $pb$La más compacta$pb$, $pb$Una torre pequeña para la mesilla, el escritorio o una habitación pequeña. Consume como máximo 7,5 W y el fabricante indica entre 20 y 43 dB según la velocidad, con opción de apagar pitidos y pantalla. Tiene 4 velocidades más una turbo, oscilación regulable a 30°, 60° o 90°, mando a distancia y temporizador de hasta 12 horas. Es la opción más barata de la guía. Por tamaño, no esperes que refresque un salón entero: su aire es más concentrado.$pb$, array[$pb$Ocupa muy poco$pb$, $pb$Consumo máximo de 7,5 W$pb$, $pb$Pitidos y pantalla desactivables$pb$]::text[], array[$pb$Poco caudal para estancias grandes$pb$, $pb$Pensado para uso cercano$pb$]::text[], $pb$[{"label":"Formato","value":"Torre compacta"},{"label":"Potencia","value":"7,5 W"},{"label":"Ruido","value":"20-43 dB"},{"label":"Velocidades","value":"4 + turbo"},{"label":"Temporizador","value":"Hasta 12 h"}]$pb$::jsonb);
