values ((select id from guides where slug = $pb$depiladoras-ipl-y-cuidado-facial$pb$), 1, $pb$Philips Lumea IPL serie 8000 (BRI944)$pb$, $pb$Mejor en general$pb$, $pb$La opción más guiada para quien empieza con la IPL. Su sistema SenseIQ incluye un sensor que detecta tu tono de piel y te indica qué ajuste de luz puedes usar, y la app gratuita de Lumea te acompaña sesión a sesión. Trae dos accesorios, para cuerpo y cara, que activan el programa de cada zona al conectarse. Funciona con cable, así que no dependes de la batería. Lo que no trae es accesorio específico para la zona del bikini, que sí tiene la serie 7000.$pb$, array[$pb$Sensor que recomienda el ajuste de luz$pb$, $pb$Accesorios que activan el programa de cada zona$pb$, $pb$App gratuita que guía las sesiones$pb$]::text[], array[$pb$Sin accesorio específico para bikini$pb$, $pb$Hay que usarla cerca de un enchufe$pb$]::text[], $pb$[{"label":"Tecnología","value":"IPL con SenseIQ"},{"label":"Accesorios","value":"2 (cuerpo y cara)"},{"label":"Alimentación","value":"Cable"},{"label":"App","value":"Lumea (gratuita)"},{"label":"Modelo","value":"BRI944/00"}]$pb$::jsonb);
