insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$depiladoras-ipl-y-cuidado-facial$pb$), 2, $pb$Philips Lumea IPL serie 7000$pb$, $pb$Con accesorio para el bikini$pb$, $pb$Si quieres cubrir también la zona del bikini, la serie 7000 trae tres accesorios: cuerpo, cara y bikini, y el facial incluye un filtro de luz integrado. Tienes cinco intensidades para elegir y la app de Lumea te guía durante las sesiones. Según el fabricante, al principio se usa cada dos semanas y después una vez al mes, y depilar las dos piernas lleva unos 15 minutos. No tiene el sensor de tono de piel de la 8000, así que el ajuste lo eliges tú.$pb$, array[$pb$Tres accesorios, incluido el de bikini$pb$, $pb$Filtro de luz en el accesorio facial$pb$, $pb$Cinco intensidades$pb$]::text[], array[$pb$Sin sensor de tono de piel$pb$, $pb$La ficha no indica si es con cable o batería$pb$]::text[], $pb$[{"label":"Tecnología","value":"IPL"},{"label":"Accesorios","value":"3 (cuerpo, cara y bikini)"},{"label":"Intensidades","value":"5"},{"label":"App","value":"Lumea (gratuita)"}]$pb$::jsonb);
