values ((select id from guides where slug = $pb$depiladoras-ipl-y-cuidado-facial$pb$), 3, $pb$Foreo Luna 3 (piel mixta)$pb$, $pb$Limpieza facial de silicona$pb$, $pb$Un cepillo de limpieza facial con puntos de contacto de silicona y pulsaciones T-Sonic. La marca propone una limpieza de un minuto y añade una segunda función de masaje facial a baja frecuencia, con varios programas. Al ser de silicona, no tiene cabezales que reponer y se limpia con agua y jabón neutro. Esta versión está pensada para piel mixta, así que revisa que elijas la variante adecuada a la tuya. Su principal pega es que cuesta más que el Beurer y no ofrece cabezales distintos.$pb$, array[$pb$Silicona: sin cabezales de recambio$pb$, $pb$Función de masaje facial$pb$, $pb$Fácil de limpiar$pb$]::text[], array[$pb$Hay versiones según tipo de piel: elige bien$pb$, $pb$Más caro que el Beurer$pb$]::text[], $pb$[{"label":"Material","value":"Silicona"},{"label":"Tecnología","value":"Pulsaciones T-Sonic"},{"label":"Tipo de piel","value":"Mixta"},{"label":"Funciones","value":"Limpieza y masaje"},{"label":"Modelo","value":"LUNA 3 (F9144)"}]$pb$::jsonb);
