values ((select id from guides where slug = $pb$depiladoras-ipl-y-cuidado-facial$pb$), 4, $pb$Beurer FC 95 con 4 cabezales$pb$, $pb$Si quieres gastar lo mínimo$pb$, $pb$La opción más asequible de la guía para empezar con un cepillo facial. Trae cuatro cabezales para distintos tipos de piel y combina rotación y oscilación con tres niveles de intensidad. Tiene un temporizador que se detiene cada 20 segundos para avisarte de que cambies de zona, y protección IPX7 para usarlo en la ducha. A cambio, los cabezales se gastan con el uso y habrá que reponerlos, un pequeño gasto extra que el Foreo no tiene.$pb$, array[$pb$Cuatro cabezales incluidos$pb$, $pb$Tres intensidades y temporizador por zonas$pb$, $pb$Resistente al agua IPX7$pb$]::text[], array[$pb$Hay que reponer los cabezales$pb$, $pb$Cabezales de recambio aparte$pb$]::text[], $pb$[{"label":"Cabezales","value":"4"},{"label":"Movimiento","value":"Rotación y oscilación"},{"label":"Intensidades","value":"3"},{"label":"Temporizador","value":"Aviso cada 20 s"},{"label":"Resistencia al agua","value":"IPX7"}]$pb$::jsonb);
