values ((select id from guides where slug = $pb$camaras-de-seguridad-y-timbres-inteligentes$pb$), 1, $pb$Tapo C410 exterior a batería$pb$, $pb$Mejor en general$pb$, $pb$La forma más sencilla de poner una cámara fuera sin hacer obra. Funciona con batería, así que no necesita enchufe, y el fabricante habla de hasta 180 días con una carga. Graba en 2K, tiene visión nocturna en color con focos integrados hasta unos 9 metros, audio bidireccional y avisos cuando detecta personas, lo que reduce las notificaciones inútiles. Guarda en microSD de hasta 512 GB o en la nube. No gira: lo que cubre depende de dónde la cuelgues.$pb$, array[$pb$Sin cables ni enchufes$pb$, $pb$Detección de personas$pb$, $pb$Visión nocturna en color$pb$]::text[], array[$pb$Hay que recargar la batería$pb$, $pb$Ángulo fijo, sin giro$pb$]::text[], $pb$[{"label":"Resolución","value":"2K (3 MP)"},{"label":"Alimentación","value":"Batería 6400 mAh"},{"label":"Autonomía","value":"Hasta 180 días"},{"label":"Visión nocturna","value":"En color, hasta 9 m"},{"label":"Almacenamiento","value":"microSD hasta 512 GB o nube"}]$pb$::jsonb);
