values ((select id from guides where slug = $pb$camaras-de-seguridad-y-timbres-inteligentes$pb$), 2, $pb$Tapo C210 interior 360°$pb$, $pb$Para vigilar dentro de casa$pb$, $pb$La opción más barata de la guía y la única pensada solo para interior. Gira 360° en horizontal y 114° en vertical, así que desde un rincón cubre una habitación entera, y puede seguir lo que se mueve. Graba en 2K, tiene visión nocturna hasta 9 metros, audio bidireccional para hablar con tu mascota y detección de llanto de bebé tras actualizar el firmware. Guarda en microSD (no incluida) de hasta 512 GB o en la nube.$pb$, array[$pb$Giro de 360° y seguimiento$pb$, $pb$Audio bidireccional$pb$, $pb$Detección de llanto de bebé$pb$]::text[], array[$pb$Solo para interior$pb$, $pb$Tarjeta microSD no incluida$pb$]::text[], $pb$[{"label":"Resolución","value":"2K (3 MP)"},{"label":"Giro","value":"360° horizontal, 114° vertical"},{"label":"Visión nocturna","value":"Hasta 9 m"},{"label":"Almacenamiento","value":"microSD hasta 512 GB o nube"},{"label":"Uso","value":"Interior"}]$pb$::jsonb);
