values ((select i.id from guide_items i where i.guide_id = (select id from guides where slug = $pb$camaras-de-seguridad-y-timbres-inteligentes$pb$) and i.position = 2), 'amazon', $pb$B095CLQ1PT$pb$, $pb$https://www.amazon.es/dp/B095CLQ1PT$pb$, 0);
insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$camaras-de-seguridad-y-timbres-inteligentes$pb$), 3, $pb$Tapo C530WS exterior 360° 3K$pb$, $pb$Para cubrir un jardín entero$pb$, $pb$Si tienes un patio o jardín amplio y un enchufe cerca, esta cámara gira 360° en horizontal y 130° en vertical y sigue el movimiento, de modo que una sola cubre mucho terreno. Graba en 3K, tiene visión nocturna en color, distingue personas, vehículos y mascotas y lleva sirena de 85 dB con luces. Es IP66 y la ficha indica que funciona entre -20 °C y 45 °C. Ojo: no tiene batería, se alimenta con adaptador de corriente.$pb$, array[$pb$Giro completo y seguimiento$pb$, $pb$Distingue personas, vehículos y mascotas$pb$, $pb$Sirena y luces disuasorias$pb$]::text[], array[$pb$Necesita enchufe: sin batería$pb$, $pb$Al girar puede enfocar zonas que no son tuyas: configura bien los límites$pb$]::text[], $pb$[{"label":"Resolución","value":"3K (5 MP)"},{"label":"Giro","value":"360° horizontal, 130° vertical"},{"label":"Protección","value":"IP66"},{"label":"Sirena","value":"85 dB"},{"label":"Alimentación","value":"Adaptador de corriente"}]$pb$::jsonb);
