values ((select i.id from guide_items i where i.guide_id = (select id from guides where slug = $pb$camaras-de-seguridad-y-timbres-inteligentes$pb$) and i.position = 3), 'amazon', $pb$B0DY94MCLN$pb$, $pb$https://www.amazon.es/dp/B0DY94MCLN$pb$, 0);
insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$camaras-de-seguridad-y-timbres-inteligentes$pb$), 4, $pb$Reolink RLC-520A PoE 5 MP$pb$, $pb$Para una instalación fija$pb$, $pb$Para quien quiere una instalación seria y sin depender del wifi. Es una cámara tipo cúpula que recibe datos y corriente por un único cable de red (PoE), lo que la hace muy estable. Graba a 5 MP (2560 x 1920) con micrófono, distingue personas, vehículos y mascotas, y admite grabación continua, por movimiento o programada en grabador Reolink NVR, servidor FTP o microSD. Es la que más trabajo de instalación pide: hay que pasar cable y contar con un switch o grabador PoE.$pb$, array[$pb$Conexión por cable, sin cortes de wifi$pb$, $pb$Grabación continua o programada$pb$, $pb$Detección de personas y vehículos$pb$]::text[], array[$pb$Necesita pasar cable de red$pb$, $pb$Requiere switch o grabador compatible con PoE$pb$]::text[], $pb$[{"label":"Resolución","value":"5 MP (2560 x 1920)"},{"label":"Conexión","value":"PoE (cable Ethernet)"},{"label":"Formato","value":"Cúpula"},{"label":"Grabación","value":"NVR, FTP o microSD"},{"label":"Uso","value":"Exterior"}]$pb$::jsonb);
