insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$camaras-de-seguridad-y-timbres-inteligentes$pb$), 5, $pb$Tapo D210 timbre con cámara 2K$pb$, $pb$Para saber quién llama$pb$, $pb$Un timbre con cámara te deja ver y hablar con quien llama desde el móvil, también cuando no estás en casa. El D210 graba en 2K, tiene audio bidireccional, visión nocturna hasta 10 metros y avisos por movimiento. Funciona con batería, con una autonomía que el fabricante cifra en unos seis meses, y es IP66, así que aguanta la intemperie. Es el más caro de la guía. Colócalo de forma que capte tu puerta y no la acera o el rellano del vecino.$pb$, array[$pb$Habla con quien llama desde el móvil$pb$, $pb$Batería, sin cablear el timbre$pb$, $pb$Resistente al agua IP66$pb$]::text[], array[$pb$El más caro de la guía$pb$, $pb$Hay que recargarlo cada pocos meses$pb$]::text[], $pb$[{"label":"Resolución","value":"2K"},{"label":"Alimentación","value":"Batería (unos 6 meses)"},{"label":"Visión nocturna","value":"Hasta 10 m"},{"label":"Protección","value":"IP66"},{"label":"Audio","value":"Bidireccional"}]$pb$::jsonb);
