values ((select id from guides where slug = $pb$piscinas-desmontables-y-depuradoras$pb$), 1, $pb$Intex Prism Frame 366 cm con depuradora$pb$, $pb$Mejor en general$pb$, $pb$La opción para quien no quiere complicarse: viene con depuradora de cartucho incluida, de 2006 litros por hora, así que sacas de la caja todo lo necesario para empezar. Es redonda, de 366 x 76 cm, con 6503 litros, y el fabricante indica capacidad para 4 personas. La lona es de triple capa, con el interior imitando gresite, y la estructura tubular tiene acabado anticorrosión. La depuradora incluida tiene menos caudal que las otras dos de la guía; si quieres más margen, puedes cambiarla después.$pb$, array[$pb$Depuradora incluida$pb$, $pb$Lona de triple capa$pb$, $pb$Tapón de vaciado con conexión a manguera$pb$]::text[], array[$pb$Depuradora incluida de caudal modesto$pb$, $pb$Redonda: ocupa más en un patio alargado$pb$]::text[], $pb$[{"label":"Medidas","value":"366 x 76 cm"},{"label":"Capacidad","value":"6503 L"},{"label":"Depuradora","value":"Cartucho, 2006 L/h (incluida)"},{"label":"Forma","value":"Redonda"},{"label":"Usuarios","value":"4 personas"}]$pb$::jsonb);
