insert into guide_items (guide_id, position, name, award, summary_md, pros, cons, specs)
values ((select id from guides where slug = $pb$piscinas-desmontables-y-depuradoras$pb$), 2, $pb$Intex Small Frame 450 x 220 cm$pb$, $pb$Para familias$pb$, $pb$La más grande de la guía: 450 x 220 x 84 cm y 7127 litros, con forma rectangular, que encaja mejor en patios alargados. La estructura es de acero con tratamiento antióxido y el fabricante calcula unos 30 minutos de montaje. La lona es de tres capas y tiene tapón de vaciado conectable a manguera. No incluye depuradora, pero trae conexiones de 32 mm, el mismo diámetro que usan las dos depuradoras de esta guía. Pesa unos 39 kg en la caja, así que necesitarás ayuda para moverla.$pb$, array[$pb$Gran capacidad para varios bañistas$pb$, $pb$Forma rectangular$pb$, $pb$Montaje en unos 30 minutos$pb$]::text[], array[$pb$Depuradora no incluida$pb$, $pb$Necesita bastante espacio llano$pb$]::text[], $pb$[{"label":"Medidas","value":"450 x 220 x 84 cm"},{"label":"Capacidad","value":"7127 L"},{"label":"Estructura","value":"Acero con epoxi antióxido"},{"label":"Conexiones","value":"32 mm"},{"label":"Peso","value":"39,05 kg"}]$pb$::jsonb);
