values ((select id from guides where slug = $pb$piscinas-desmontables-y-depuradoras$pb$), 3, $pb$Intex Small Frame 300 x 200 cm$pb$, $pb$La más compacta$pb$, $pb$Para patios pequeños o terrazas, esta Small Frame se queda en 300 x 200 x 75 cm y 3834 litros, casi la mitad de agua que su hermana mayor, lo que también se nota al llenarla y en el mantenimiento. Comparte estructura de acero con epoxi antióxido, lona de tres capas y tapón de vaciado conectable a manguera, y el fabricante la recomienda para espacios pequeños. Como la grande, no trae depuradora, aunque tiene conexiones de 32 mm para añadirla.$pb$, array[$pb$Ocupa poco$pb$, $pb$Menos agua que llenar y tratar$pb$, $pb$Mismas conexiones de 32 mm$pb$]::text[], array[$pb$Depuradora no incluida$pb$, $pb$Poca profundidad para adultos$pb$]::text[], $pb$[{"label":"Medidas","value":"300 x 200 x 75 cm"},{"label":"Capacidad","value":"3834 L"},{"label":"Estructura","value":"Acero con epoxi antióxido"},{"label":"Conexiones","value":"32 mm"},{"label":"Forma","value":"Rectangular"}]$pb$::jsonb);
