values ((select id from guides where slug = $pb$piscinas-desmontables-y-depuradoras$pb$), 4, $pb$Intex Krystal Clear arena 3500 L/h$pb$, $pb$Depuradora para muchas temporadas$pb$, $pb$Si vas a montar la piscina varios veranos, una depuradora de arena es una buena inversión. Esta filtra 3500 litros por hora y está indicada para piscinas de hasta 17.000 litros. Su válvula tiene cuatro funciones (lavado, filtración, recirculación y desagüe), trae manómetro y un programador para ciclos diarios de 1 a 12 horas. Incluye mangueras de 32 mm. La arena o las bolas filtrantes no vienen incluidas, así que súmalas a la compra.$pb$, array[$pb$Programador diario de 1 a 12 horas$pb$, $pb$Válvula de cuatro funciones y manómetro$pb$, $pb$Margen para piscinas grandes$pb$]::text[], array[$pb$Arena o bolas filtrantes no incluidas$pb$, $pb$Más voluminosa que la de cartucho$pb$]::text[], $pb$[{"label":"Tipo","value":"Arena"},{"label":"Caudal","value":"3500 L/h"},{"label":"Piscinas","value":"Hasta 17.000 L"},{"label":"Motor","value":"90 W"},{"label":"Conexiones","value":"Mangueras de 32 mm incluidas"}]$pb$::jsonb);
