values ((select id from guides where slug = $pb$piscinas-desmontables-y-depuradoras$pb$), 5, $pb$Intex C1000 cartucho 3785 L/h$pb$, $pb$Si quieres gastar lo mínimo$pb$, $pb$La depuradora más económica de la guía. Filtra 3785 litros por hora y está indicada para piscinas de hasta 21.100 litros. Usa cartucho tipo A y lleva un indicador de tres niveles que te avisa de cuándo limpiar o cambiar el filtro, algo que se agradece si es tu primera piscina. Se conecta con mangueras de 32 mm incluidas. A cambio, tendrás que ir reponiendo cartuchos durante la temporada.$pb$, array[$pb$Indicador de cambio de cartucho$pb$, $pb$Mangueras de 32 mm incluidas$pb$, $pb$Ligera y fácil de colocar$pb$]::text[], array[$pb$Hay que reponer cartuchos$pb$, $pb$Sin programador horario en la ficha$pb$]::text[], $pb$[{"label":"Tipo","value":"Cartucho tipo A"},{"label":"Caudal","value":"3785 L/h"},{"label":"Piscinas","value":"Hasta 21.100 L"},{"label":"Peso","value":"2,95 kg"},{"label":"Conexiones","value":"32 mm"}]$pb$::jsonb);
